import { useEffect, useRef, useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';

interface SwipeNavigationConfig {
  threshold?: number;
  velocityThreshold?: number;
  routes: string[];
}

export function useSwipeNavigation({
  threshold = 120,
  velocityThreshold = 0.3,
  routes
}: SwipeNavigationConfig) {
  const navigate = useNavigate();
  const location = useLocation();
  const touchStartRef = useRef<{ x: number; y: number; time: number } | null>(null);
  const swipeOffsetRef = useRef(0);
  const isSwipingRef = useRef(false);
  const shouldAnimateRef = useRef(false);
  const routesRef = useRef(routes);
  const locationRef = useRef(location.pathname);
  routesRef.current = routes;
  locationRef.current = location.pathname;

  const [swipeOffset, setSwipeOffset] = useState(0);
  const [isSwipingHorizontally, setIsSwipingHorizontally] = useState(false);

  useEffect(() => {
    const handleTouchStart = (e: TouchEvent) => {
      const target = e.target as HTMLElement;
      if (
        target.closest('input') ||
        target.closest('select') ||
        target.closest('textarea') ||
        target.closest('[data-no-swipe]')
      ) return;

      const touch = e.touches[0];
      touchStartRef.current = { x: touch.clientX, y: touch.clientY, time: Date.now() };
      swipeOffsetRef.current = 0;
      isSwipingRef.current = false;
      shouldAnimateRef.current = false;
      setIsSwipingHorizontally(false);
      setSwipeOffset(0);
    };

    const handleTouchMove = (e: TouchEvent) => {
      if (!touchStartRef.current) return;

      const touch = e.touches[0];
      const deltaX = touch.clientX - touchStartRef.current.x;
      const deltaY = touch.clientY - touchStartRef.current.y;

      if (!isSwipingRef.current && Math.abs(deltaX) > 15) {
        if (Math.abs(deltaX) > Math.abs(deltaY) * 1.5) {
          isSwipingRef.current = true;
          // Mostra animazione solo se non siamo ai bordi
          const currentIndex = routesRef.current.indexOf(locationRef.current);
          const atStart = currentIndex === 0 && deltaX > 0;
          const atEnd = currentIndex === routesRef.current.length - 1 && deltaX < 0;
          shouldAnimateRef.current = !atStart && !atEnd;
          if (shouldAnimateRef.current) {
            setIsSwipingHorizontally(true);
          }
        }
      }

      if (isSwipingRef.current) {
        swipeOffsetRef.current = deltaX;
        if (shouldAnimateRef.current) {
          setSwipeOffset(deltaX);
        }
        e.preventDefault();
      }
    };

    const handleTouchEnd = () => {
      if (!touchStartRef.current) return;

      const deltaX = swipeOffsetRef.current;
      const deltaTime = Date.now() - touchStartRef.current.time;
      const velocity = Math.abs(deltaX) / deltaTime;

      setSwipeOffset(0);
      setIsSwipingHorizontally(false);

      if (Math.abs(deltaX) > threshold || velocity > velocityThreshold) {
        const modalOpen = document.querySelector('[data-no-swipe]');
        if (modalOpen) {
          if (deltaX > 0) {
            window.dispatchEvent(new CustomEvent('trackr:swipe-back'));
          }
        } else {
          const currentIndex = routesRef.current.indexOf(locationRef.current);
          if (currentIndex !== -1) {
            let nextIndex = -1;
            if (deltaX > 0 && currentIndex > 0) nextIndex = currentIndex - 1;
            else if (deltaX < 0 && currentIndex < routesRef.current.length - 1) nextIndex = currentIndex + 1;
            if (nextIndex !== -1) navigate(routesRef.current[nextIndex]);
          }
        }
      }

      touchStartRef.current = null;
      swipeOffsetRef.current = 0;
      isSwipingRef.current = false;
    };

    document.addEventListener('touchstart', handleTouchStart, { passive: true });
    document.addEventListener('touchmove', handleTouchMove, { passive: false });
    document.addEventListener('touchend', handleTouchEnd);
    document.addEventListener('touchcancel', handleTouchEnd);

    return () => {
      document.removeEventListener('touchstart', handleTouchStart);
      document.removeEventListener('touchmove', handleTouchMove);
      document.removeEventListener('touchend', handleTouchEnd);
      document.removeEventListener('touchcancel', handleTouchEnd);
    };
  }, [navigate, threshold, velocityThreshold]);

  return { swipeOffset, isSwipingHorizontally };
}

import { useState } from 'react';
import { apiService } from '../services/api';
import { useData } from '../contexts/DataContext';
import Layout from '../components/layout/Layout';
import Modal from '../components/common/Modal';
import ConfirmDialog from '../components/common/ConfirmDialog';
import { SkeletonAccountCard, SkeletonValue } from '../components/common/SkeletonLoader';
import { useSkeletonCount } from '../hooks/useSkeletonCount';
import type { Account, AccountFormData, CurrencyCode } from '../types';
import { SUPPORTED_CURRENCIES } from '../services/fx';
import { useTranslation } from 'react-i18next';
import { useSettings } from '../contexts/SettingsContext';

interface CurrencyRow {
  id?: number;
  currency: CurrencyCode;
  balance: number;
}

const ACCOUNT_ICONS = ['💳', '🏦', '💰', '💵', '💶', '💷', '💴', '🪙', '💸', '🏧', '📱', '💎'];

export default function AccountsPage() {
  const { t } = useTranslation();
  const { formatCurrency } = useSettings();
  const { accounts, transactions, transfers, isLoading, addAccount, updateAccount: updateAccountCache, deleteAccount: deleteAccountCache, refreshAccounts, activeProfile } = useData();
  const isViewer = activeProfile?.role === 'viewer';
  const skeletonCount = useSkeletonCount('accounts', accounts.length, isLoading, 3);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [hideBalances, setHideBalances] = useState(() => localStorage.getItem('hideBalances') === 'true');

  const toggleHideBalances = () => {
    setHideBalances(h => {
      const next = !h;
      localStorage.setItem('hideBalances', String(next));
      return next;
    });
  };

  const maskAmount = (formatted: string, positive: boolean) => {
    const masked = '•'.repeat(formatted.length);
    return <span className={positive ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'}>{masked}</span>;
  };
  const [isEditMode, setIsEditMode] = useState(false);
  const [selectedAccount, setSelectedAccount] = useState<Account | null>(null);
  const [formData, setFormData] = useState<AccountFormData>({
    name: '',
    icon: '💳',
    initial_balance: 0,
    is_favorite: false,
  });
  const [balanceInput, setBalanceInput] = useState<string>('0');
  const [currencyRows, setCurrencyRows] = useState<CurrencyRow[]>([{ currency: 'EUR', balance: 0 }]);
  const [showNameError, setShowNameError] = useState(false);
  const [isBalanceFresh, setIsBalanceFresh] = useState(true);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleteError, setDeleteError] = useState<string | null>(null);
  const [transactionCount, setTransactionCount] = useState<number>(0);

  const handleOpenModal = (account?: Account) => {
    if (account) {
      setIsEditMode(true);
      setSelectedAccount(account);
      setFormData({
        name: account.name,
        icon: account.icon,
        initial_balance: account.initial_balance,
        is_favorite: account.is_favorite || false,
      });
      // In modalità modifica, mostra il saldo corrente
      const currentBalance = account.current_balance ?? account.initial_balance;
      setBalanceInput(parseFloat(currentBalance.toFixed(2)).toString());
      // Righe valute: saldo corrente per valuta (EUR gestito dal tastierino)
      setCurrencyRows(
        (account.currencies?.length
          ? account.currencies
          : [{ id: undefined, currency: 'EUR' as CurrencyCode, initial_balance: account.initial_balance }]
        ).map(c => ({
          id: c.id,
          currency: c.currency,
          balance: parseFloat((account.balances?.[c.currency] ?? c.initial_balance).toFixed(2)),
        }))
      );
    } else {
      setIsEditMode(false);
      setSelectedAccount(null);
      setFormData({
        name: '',
        icon: '💳',
        initial_balance: 0,
        is_favorite: false,
      });
      setBalanceInput('0');
      setCurrencyRows([{ currency: 'EUR', balance: 0 }]);
    }
    setShowNameError(false);
    setIsBalanceFresh(true);
    setDeleteError(null);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setSelectedAccount(null);
    setIsEditMode(false);
  };

  const handleSubmit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();

    // Valida il nome
    if (formData.name.trim() === '' || isDuplicateAccountName) {
      setShowNameError(true);
      return;
    }

    const balanceValue = parseFloat(balanceInput) || 0;

    // Prepara i dati da inviare
    const finalFormData = isEditMode && selectedAccount
      ? {
          ...formData,
          // current_balance non è una colonna DB: è initial_balance + Σtransazioni.
          // Per ottenere il saldo corrente desiderato, ricalcola initial_balance di conseguenza.
          initial_balance: balanceValue - ((selectedAccount.current_balance ?? selectedAccount.initial_balance) - selectedAccount.initial_balance),
        }
      : {
          ...formData,
          initial_balance: balanceValue,
        };

    try {
      if (isEditMode && selectedAccount) {
        const updatedAccount = await apiService.updateAccount(selectedAccount.id, finalFormData);
        updateAccountCache(updatedAccount);

        let didCurrencyOps = false;
        // Riga EUR: aggiorna anche account_currencies (accounts.initial_balance già aggiornato sopra, compat)
        const eurRow = selectedAccount.currencies?.find(c => c.currency === 'EUR');
        if (eurRow && finalFormData.initial_balance !== eurRow.initial_balance) {
          await apiService.updateAccountCurrency(eurRow.id, finalFormData.initial_balance);
          didCurrencyOps = true;
        }
        // Righe non-EUR: saldo desiderato → initial ricalcolato (stessa logica della riga EUR)
        const prevRows = selectedAccount.currencies?.filter(c => c.currency !== 'EUR') ?? [];
        const uiRows = currencyRows.filter(r => r.currency !== 'EUR');
        for (const row of uiRows) {
          const existing = prevRows.find(c => c.currency === row.currency);
          if (!existing) {
            await apiService.addAccountCurrency(selectedAccount.id, row.currency, row.balance);
            didCurrencyOps = true;
          } else {
            const newInitial = row.balance - ((selectedAccount.balances?.[row.currency] ?? 0) - existing.initial_balance);
            if (newInitial !== existing.initial_balance) {
              await apiService.updateAccountCurrency(existing.id, newInitial);
              didCurrencyOps = true;
            }
          }
        }
        // Righe rimosse in UI
        for (const prev of prevRows) {
          if (uiRows.some(r => r.currency === prev.currency)) continue;
          try {
            await apiService.removeAccountCurrency(prev.id);
            didCurrencyOps = true;
          } catch (err) {
            if (err instanceof Error && err.message === 'currency_in_use') {
              alert(t('accounts.currencyInUse'));
              setCurrencyRows(rows => [...rows, {
                id: prev.id,
                currency: prev.currency,
                balance: selectedAccount.balances?.[prev.currency] ?? prev.initial_balance,
              }]);
            } else {
              throw err;
            }
          }
        }
        if (didCurrencyOps) await refreshAccounts();
      } else {
        const newAccount = await apiService.createAccount(finalFormData);
        for (const row of currencyRows.filter(r => r.currency !== 'EUR')) {
          await apiService.addAccountCurrency(newAccount.id, row.currency, row.balance);
        }
        addAccount(newAccount);
        if (currencyRows.length > 1) await refreshAccounts();
      }
      handleCloseModal();
    } catch (error) {
      console.error('Errore salvataggio conto:', error);
      alert('Errore durante il salvataggio del conto');
    }
  };

  const availableCurrencies = SUPPORTED_CURRENCIES.filter(c => !currencyRows.some(r => r.currency === c));

  const handleRemoveCurrency = (currency: CurrencyCode) => {
    setCurrencyRows(rows => rows.filter(r => r.currency !== currency));
  };

  const handleNumberClick = (num: string) => {
    // Se è il primo click dopo l'apertura del modal, sostituisci il valore
    if (isBalanceFresh) {
      setBalanceInput(num);
      setIsBalanceFresh(false);
    } else if (balanceInput === '0') {
      setBalanceInput(num);
    } else {
      setBalanceInput(balanceInput + num);
    }
  };

  const handleBackspace = () => {
    setIsBalanceFresh(false);
    if (balanceInput.length > 1) {
      setBalanceInput(balanceInput.slice(0, -1));
    } else {
      setBalanceInput('0');
    }
  };

  const handleToggleSign = () => {
    setIsBalanceFresh(false);
    if (balanceInput === '0') return;

    if (balanceInput.startsWith('-')) {
      setBalanceInput(balanceInput.substring(1));
    } else {
      setBalanceInput('-' + balanceInput);
    }
  };

  const handleDelete = async () => {
    if (!selectedAccount) return;

    try {
      await apiService.deleteAccount(selectedAccount.id);
      deleteAccountCache(selectedAccount.id);
      setShowDeleteConfirm(false);
      handleCloseModal();
    } catch (error: any) {
      console.error('Errore eliminazione conto:', error);

      // Controlla se è un errore 400 con transazioni associate
      if (error.response?.status === 400 && error.response?.data?.detail) {
        const detail = error.response.data.detail;
        // Estrai il numero di transazioni dal messaggio di errore
        const match = detail.match(/(\d+) transaction/);
        const count = match ? parseInt(match[1]) : 0;
        setTransactionCount(count);
        setDeleteError(detail);
      } else {
        setDeleteError('Errore durante l\'eliminazione del conto');
      }
    }
  };

  const handleToggleFavorite = async (account: Account, e: React.MouseEvent) => {
    e.stopPropagation(); // Previene l'apertura del modal

    // Se è già preferito, non fare nulla (almeno un preferito deve esserci sempre)
    if (account.is_favorite) return;

    // Trova i conti che erano preferiti (da aggiornare nel DB)
    const prevFavorites = accounts.filter(acc => acc.id !== account.id && acc.is_favorite);

    // Aggiorna la cache: rimuovi preferito dagli altri e imposta questo
    prevFavorites.forEach(acc => updateAccountCache({ ...acc, is_favorite: false }));
    updateAccountCache({ ...account, is_favorite: true });

    try {
      // Persisti nel DB: sia la rimozione dai vecchi preferiti che il nuovo
      await Promise.all([
        ...prevFavorites.map(acc => apiService.updateAccount(acc.id, { is_favorite: false })),
        apiService.updateAccount(account.id, { is_favorite: true }),
      ]);
    } catch (error) {
      console.error('Errore aggiornamento preferito:', error);
      await refreshAccounts();
    }
  };

  const formatAmountDisplay = (value: string): string => {
    const negative = value.startsWith('-');
    const abs = negative ? value.slice(1) : value;
    const [intStr, decStr] = abs.split('.');
    const intFormatted = (parseInt(intStr) || 0).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
    const result = decStr !== undefined ? `${intFormatted}.${decStr}` : intFormatted;
    return negative ? `-${result}` : result;
  };

  const accountTotals = accounts.map(a => a.total_base);
  const totalLiquidity = accountTotals.some(v => v == null)
    ? null
    : accountTotals.reduce((s: number, v) => s + (v as number), 0);
  // Fallback quando i tassi non sono disponibili: somma dei soli saldi EUR
  const eurLiquidity = accounts.reduce((sum, acc) => sum + (acc.balances?.['EUR'] ?? acc.current_balance ?? acc.initial_balance), 0);
  const displayLiquidity = totalLiquidity ?? eurLiquidity;
  const normalizedAccountName = formData.name.trim().toLocaleLowerCase();
  const isDuplicateAccountName = normalizedAccountName !== '' && accounts.some(
    (account) => account.id !== selectedAccount?.id && account.name.trim().toLocaleLowerCase() === normalizedAccountName
  );
  const isAccountFormValid = formData.name.trim() !== '' && !isDuplicateAccountName;
  const openDeleteDialog = () => {
    if (!selectedAccount) return;
    const linkedTransactionsCount = transactions.filter((tx) => tx.account_id === selectedAccount.id).length;
    const linkedTransfersCount = transfers.filter(
      (tr) => tr.from_account_id === selectedAccount.id || tr.to_account_id === selectedAccount.id
    ).length;
    const linkedItemsCount = linkedTransactionsCount + linkedTransfersCount;
    if (linkedItemsCount > 0) {
      setTransactionCount(linkedItemsCount);
      setDeleteError('linked-transactions');
    } else {
      setTransactionCount(0);
      setDeleteError(null);
    }
    setShowDeleteConfirm(true);
  };

  return (
    <Layout>
      <div className="space-y-6">
        {/* Totale liquidità */}
        {(isLoading || accounts.length > 0) && (
          <div className="sticky -top-3 z-20 -mx-4 px-4 -mt-3 pt-4 pb-6 bg-gray-50 dark:bg-gray-900 relative">
          <div className="card py-6">
            <div className="text-sm text-gray-500 dark:text-gray-400 mb-1 text-center">{t('accounts.totalLiquidity')}</div>
            <div className="flex items-center justify-center">
              <div className="flex-1" />
              <div className="text-4xl font-bold">
                {isLoading
                  ? <SkeletonValue className="h-10 w-40 animate-pulse inline-block" />
                  : hideBalances
                    ? maskAmount(formatCurrency(displayLiquidity), displayLiquidity >= 0)
                    : <span className={displayLiquidity >= 0 ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'}>{formatCurrency(displayLiquidity)}</span>}
              </div>
              <div className="flex-1 flex justify-end pr-2">
                <button
                  onClick={toggleHideBalances}
                  className="text-gray-400 dark:text-gray-500 text-xl outline-none focus:outline-none select-none"
                  style={{ WebkitTapHighlightColor: 'transparent' }}
                >
                  {hideBalances ? '🙈' : '👁️'}
                </button>
              </div>
            </div>
            {totalLiquidity === null && !isLoading && (
              <div className="text-xs text-amber-500 text-center mt-1">⚠ {t('accounts.ratesUnavailable')}</div>
            )}
          </div>
          {/* Gradient fade */}
          <div className="absolute left-0 right-0 h-8 bg-gradient-to-b from-gray-50 dark:from-gray-900 to-transparent pointer-events-none" style={{ top: '100%' }} />
          </div>
        )}

        {/* Lista conti */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {isLoading
            ? Array.from({ length: skeletonCount }).map((_, i) => <SkeletonAccountCard key={i} />)
            : [...accounts].sort((a, b) => (b.current_balance ?? b.initial_balance) - (a.current_balance ?? a.initial_balance)).map((account) => (
              <div
                key={account.id}
                className="card hover:shadow-lg transition-shadow cursor-pointer"
                onClick={() => handleOpenModal(account)}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-3 flex-1">
                    <div className="text-4xl">{account.icon}</div>
                    <div className="flex-1">
                      <h3 className="font-semibold text-gray-900 dark:text-gray-100">
                        {account.name}
                      </h3>
                    </div>
                  </div>
                  <div className="flex items-center gap-4">
                    {(() => {
                      const multi = (account.currencies?.length ?? 0) > 1;
                      const bal = multi
                        ? (account.total_base ?? account.balances?.['EUR'] ?? 0)
                        : (account.current_balance ?? account.initial_balance);
                      return (
                        <div className="text-right">
                          <div className={`text-lg font-bold ${bal >= 0 ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'}`}>
                            {hideBalances ? maskAmount(formatCurrency(bal), bal >= 0) : formatCurrency(bal)}
                            {multi && account.total_base == null && (
                              <span className="ml-1 text-xs align-middle" title={t('accounts.ratesUnavailable')}>⚠</span>
                            )}
                          </div>
                          {multi && !hideBalances && (
                            <div className="flex flex-wrap gap-1 mt-1 justify-end">
                              {Object.entries(account.balances ?? {}).map(([cur, v]) => (
                                <span key={cur} className="text-xs px-1.5 py-0.5 rounded bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300">
                                  {formatCurrency(v, cur)}
                                </span>
                              ))}
                            </div>
                          )}
                        </div>
                      );
                    })()}
                    <button
                      onClick={(e) => handleToggleFavorite(account, e)}
                      className="text-2xl transition-colors"
                    >
                      <span className={account.is_favorite ? 'text-yellow-400 text-3xl' : 'text-gray-300 dark:text-gray-600 text-2xl'}>★</span>
                    </button>
                  </div>
                </div>
              </div>
          ))}
          {/* Aggiungi nuovo conto */}
          {!isViewer && (
            <div
              className="card flex items-center justify-center border-2 border-dashed border-gray-200 dark:border-gray-700 cursor-pointer outline-none select-none md:col-span-2"
              style={{ WebkitTapHighlightColor: 'transparent' }}
              onClick={() => handleOpenModal()}
            >
              <div className="w-10 h-10 rounded-full border-2 border-gray-300 dark:border-gray-600 flex items-center justify-center text-gray-400 dark:text-gray-500 font-bold text-2xl">+</div>
            </div>
          )}
        </div>

        {/* Modal per creare/modificare conto */}
        <Modal
          isOpen={isModalOpen}
          onClose={handleCloseModal}
          title={isEditMode ? t('accounts.editAccount') : t('accounts.newAccount')}
        >
          <form onSubmit={handleSubmit} noValidate autoComplete="off" className="space-y-4">
            {/* Nome */}
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                {t('accounts.name')}
              </label>
              <input
                type="text"
                value={formData.name}
                autoComplete="off" autoCorrect="off" spellCheck={false}
                onChange={(e) => {
                  setFormData({ ...formData, name: e.target.value });
                  if (showNameError && e.target.value.trim() !== '') {
                    setShowNameError(false);
                  }
                }}
                className={`w-full px-4 py-2 rounded-lg border ${
                  (showNameError || isDuplicateAccountName)
                    ? 'border-red-500 dark:border-red-500'
                    : 'border-gray-300 dark:border-gray-600'
                } bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 focus:ring-2 focus:ring-primary-500 focus:border-transparent`}
                placeholder={t('accounts.namePlaceholder')}
              />
            </div>

            {/* Icona */}
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                {t('accounts.icon')}
              </label>
              <div className="grid grid-cols-6 gap-2">
                {ACCOUNT_ICONS.map((icon) => (
                  <button
                    key={icon}
                    type="button"
                    onClick={() => setFormData({ ...formData, icon })}
                    className={`aspect-square flex items-center justify-center text-2xl rounded-lg border-2 transition-colors ${
                      formData.icon === icon
                        ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20'
                        : 'border-gray-200 dark:border-gray-700 hover:border-primary-300'
                    }`}
                  >
                    {icon}
                  </button>
                ))}
              </div>
            </div>

            {/* Saldo */}
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                {isEditMode ? t('accounts.currentBalance') : t('accounts.initialBalance')}
              </label>
              {/* Display dell'importo */}
              <div className="text-center mb-4">
                <div className="text-3xl font-bold text-gray-900 dark:text-gray-100">
                  € {formatAmountDisplay(balanceInput)}
                </div>
              </div>

              {/* Tastierino numerico */}
              <div className="flex gap-2">
                {/* Griglia numeri 3x4 (sinistra) */}
                <div className="flex-1 grid grid-cols-3 gap-2">
                  {/* Numeri 1-9 */}
                  {[1, 2, 3, 4, 5, 6, 7, 8, 9].map((num) => (
                    <button
                      key={num}
                      type="button"
                      onClick={() => handleNumberClick(num.toString())}
                      className="h-14 text-2xl font-semibold rounded-lg bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors"
                    >
                      {num}
                    </button>
                  ))}
                  {/* +/- Toggle */}
                  <button
                    type="button"
                    onClick={handleToggleSign}
                    className="h-14 text-2xl font-semibold rounded-lg bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors"
                  >
                    +/−
                  </button>
                  {/* Zero */}
                  <button
                    type="button"
                    onClick={() => handleNumberClick('0')}
                    className="h-14 text-2xl font-semibold rounded-lg bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors"
                  >
                    0
                  </button>
                  {/* Virgola */}
                  <button
                    type="button"
                    onClick={() => {
                      setIsBalanceFresh(false);
                      if (!balanceInput.includes('.')) {
                        setBalanceInput(balanceInput + '.');
                      }
                    }}
                    className="h-14 text-2xl font-semibold rounded-lg bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors"
                  >
                    ,
                  </button>
                </div>

                {/* Colonna comandi (destra) */}
                <div className="flex flex-col gap-2">
                  {/* Backspace */}
                  <button
                    type="button"
                    onClick={handleBackspace}
                    className="h-14 w-14 rounded-lg bg-gray-100 dark:bg-gray-700 hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors flex items-center justify-center text-gray-900 dark:text-gray-100"
                  >
                    <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.2}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M11 17l-5-5 5-5" />
                      <path strokeLinecap="round" strokeLinejoin="round" d="M19 12H7" />
                    </svg>
                  </button>
                  <button
                    type="button"
                    onClick={() => handleSubmit()}
                    disabled={!isAccountFormValid}
                    className="flex-1 w-14 text-2xl font-bold rounded-lg bg-primary-500 text-white hover:bg-primary-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:bg-primary-500"
                  >
                    ✓
                  </button>
                </div>
              </div>
            </div>

            {/* Valute aggiuntive (il tastierino sopra è la riga EUR) */}
            <div>
              <label className="block text-sm text-gray-600 dark:text-gray-400 mb-2">{t('accounts.currencies')}</label>
              <div className="space-y-2">
                {currencyRows.filter(r => r.currency !== 'EUR').map((row) => (
                  <div key={row.currency} className="flex items-center gap-2">
                    <span className="w-12 text-sm font-mono text-gray-500 dark:text-gray-400">{row.currency}</span>
                    <input
                      type="number" step="0.01" value={row.balance}
                      onChange={e => setCurrencyRows(rows => rows.map(r => r.currency === row.currency ? { ...r, balance: Number(e.target.value) } : r))}
                      className="input-field flex-1"
                      aria-label={t('accounts.initialBalanceFor', { currency: row.currency })}
                    />
                    <button type="button" onClick={() => handleRemoveCurrency(row.currency)}
                      className="text-red-500 px-2 text-lg" aria-label="remove">×</button>
                  </div>
                ))}
              </div>
              {availableCurrencies.length > 0 && (
                <div className="flex gap-2 mt-2">
                  {availableCurrencies.map(c => (
                    <button key={c} type="button"
                      title={t('accounts.addCurrency')}
                      onClick={() => setCurrencyRows(rows => [...rows, { currency: c, balance: 0 }])}
                      className="px-3 py-1.5 rounded-lg border border-dashed border-gray-300 dark:border-gray-600 text-sm text-gray-500 dark:text-gray-400">
                      + {c}
                    </button>
                  ))}
                </div>
              )}
            </div>

            {isEditMode && (
              <button
                type="button"
                onClick={openDeleteDialog}
                className="w-full px-4 py-2.5 rounded-lg bg-red-500 text-white hover:bg-red-600 transition-colors text-sm font-medium flex items-center justify-center gap-2"
              >
                <span className="text-base leading-none">🗑️</span>
                <span>{t('common.delete')}</span>
              </button>
            )}
          </form>
        </Modal>

        {/* Dialog di conferma eliminazione */}
        <ConfirmDialog
          isOpen={showDeleteConfirm}
          onClose={() => {
            setShowDeleteConfirm(false);
            setDeleteError(null);
          }}
          onConfirm={deleteError ? () => {} : handleDelete}
          title={deleteError ? t('accounts.cannotDeleteTitle') : t('accounts.deleteTitle')}
          message={
            deleteError
              ? t('accounts.cannotDeleteMessage', { name: selectedAccount?.name, count: transactionCount })
              : t('accounts.deleteMessage', { name: selectedAccount?.name })
          }
          confirmText={deleteError ? t('common.ok') : t('common.delete')}
          cancelText={deleteError ? undefined : t('common.cancel')}
          isDestructive={!deleteError}
        />
      </div>
    </Layout>
  );
}

