                  <div className="space-y-3">
                    {selectedCategory.subcategories.map((sub) => {
                      const subAmount = sub.total_amount || 0;
                      const pct = catTotal > 0 ? (subAmount / catTotal) * 100 : 0;
                      return (
                        <div key={sub.id}>
                          <div className="flex items-center justify-between mb-1">
                            {editingSubcategoryId === sub.id ? (
                              <input
                                autoFocus
                                className="flex-1 text-sm bg-transparent border-b border-primary-500 outline-none text-gray-900 dark:text-gray-100 mr-2"
                                value={editingSubcategoryName}
                                onChange={e => setEditingSubcategoryName(e.target.value)}
                                onBlur={() => setEditingSubcategoryId(null)}
                                onKeyDown={e => {
                                  if (e.key === 'Enter') { e.preventDefault(); handleSubcategoryRename(sub.id); }
                                  if (e.key === 'Escape') setEditingSubcategoryId(null);
                                }}
                              />
                            ) : (
                              <span
                                className="text-sm text-gray-900 dark:text-gray-100 cursor-pointer flex-1 min-w-0 truncate"
                                onClick={() => { setEditingSubcategoryId(sub.id); setEditingSubcategoryName(sub.name); }}
                              >
                                {sub.name}
                              </span>
                            )}
                            <div className="flex items-center gap-2 shrink-0 ml-2">
                              {subAmount > 0 && (
                                <span className="text-sm font-medium text-gray-700 dark:text-gray-300">
                                  {formatCurrency(subAmount)}
                                </span>
                              )}
                              <button
                                onClick={() => handleDeleteSubcategory(sub.id)}
                                className="text-red-400 hover:text-red-600 text-sm"
                              >
                                🗑️
                              </button>
                            </div>
                          </div>
                          <div className="relative w-full h-5 bg-gray-100 dark:bg-gray-700 rounded overflow-hidden">
                            <div
                              className="h-full transition-all duration-500"
                              style={{ width: `${pct}%`, backgroundColor: catColor, opacity: 0.75 }}
                            />
                            <div className="absolute inset-0 flex items-center justify-end pr-2">
                              <span className="text-xs font-bold text-gray-800 dark:text-gray-100">
                                {catTotal > 0 ? `${pct.toFixed(1)}%` : '—'}
                              </span>
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              );
            })()}

            {/* Form nuova sottocategoria */}
            {!showSubcategoryForm ? (
              <div className="flex justify-center py-3">
                <button
                  type="button"
                  onClick={() => setShowSubcategoryForm(true)}
                  className="flex items-center gap-2 px-4 py-2 rounded-lg bg-primary-500 text-white hover:bg-primary-600 transition-colors text-sm font-medium"
                >
                  <span className="text-xl">+</span>
                  <span>{t('common.newSubcategory')}</span>
                </button>
              </div>
            ) : (
              <form onSubmit={handleSubcategorySubmit} noValidate autoComplete="off" className="space-y-3">
                <h4 className="text-sm font-medium text-gray-700 dark:text-gray-300">
                  {t('common.newSubcategory')}
                </h4>

                <div>
                  <input
                    type="text"
                    value={subcategoryFormData.name}
                    onChange={(e) => setSubcategoryFormData({ ...subcategoryFormData, name: e.target.value })}
                    className={`w-full px-3 py-2 rounded-lg border ${
                      isDuplicateSubcategoryName ? 'border-red-500 dark:border-red-500' : 'border-gray-300 dark:border-gray-600'
                    } bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 text-sm`}
                    placeholder={t('common.subcategoryName')}
                    autoComplete="off" autoCorrect="off" spellCheck={false}
                    autoFocus
                  />
                </div>
                <div className="flex gap-2">
                  <button
                    type="button"
                    onClick={() => {
                      setShowSubcategoryForm(false);
                      setSubcategoryFormData({ name: '' });
                    }}
                    className="flex-1 btn-secondary"
                  >
                    {t('common.cancel')}
                  </button>
                  <button
                    type="submit"
                    disabled={!isSubcategoryFormValid}
                    className="flex-1 btn-primary disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {t('common.add')}
                  </button>
                </div>
              </form>
            )}
          </div>
        </Modal>

        {/* Modal categoria */}
        <Modal
          isOpen={isCategoryModalOpen}
          onClose={() => {
            setIsCategoryModalOpen(false);
          }}
          onBackdropClick={() => {
            setIsCategoryModalOpen(false);
            setIsSubcategoryModalOpen(false);
            setShowSubcategoryForm(false);
            setSubcategoryFormData({ name: '' });
          }}
          title={isEditMode ? t('categories.editCategory') : t('categories.newCategory')}
        >
          <form onSubmit={handleCategorySubmit} noValidate autoComplete="off" className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                {t('categories.name')}
              </label>
              <input
                type="text"
                value={categoryFormData.name}
                onChange={(e) => setCategoryFormData({ ...categoryFormData, name: e.target.value })}
                className={`w-full px-4 py-2 rounded-lg border ${
                  isDuplicateCategoryName ? 'border-red-500 dark:border-red-500' : 'border-gray-300 dark:border-gray-600'
                } bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100`}
                autoComplete="off" autoCorrect="off" spellCheck={false}
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                {t('categories.color')}
              </label>
              <div className="flex items-center gap-3">
                <div className="flex gap-2 overflow-x-auto p-2 flex-1" style={{ scrollbarWidth: 'none' }}>
                  {PRESET_COLORS.map(c => (
                    <button
                      key={c}
                      type="button"
                      onClick={() => setCategoryFormData(prev => ({ ...prev, color: c }))}
                      className={`flex-shrink-0 w-7 h-7 rounded-full transition-transform ${categoryFormData.color === c ? 'scale-125 ring-2 ring-offset-1 ring-gray-400 dark:ring-gray-500' : 'hover:scale-110'}`}
                      style={{ backgroundColor: c }}
                    />
                  ))}
                </div>
                <button
                  type="button"
                  onClick={() => setCategoryFormData(prev => ({ ...prev, color: randomPresetColor() }))}
                  className="shrink-0 text-xs text-gray-500 dark:text-gray-400 hover:text-primary-500 dark:hover:text-primary-400 border border-gray-300 dark:border-gray-600 rounded-lg px-2 py-1"
                >
                  {t('categories.randomColor')}
                </button>
              </div>
            </div>

            <div className="mt-1">
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                {t('categories.icon')}
              </label>
              <div className="max-h-64 overflow-y-auto space-y-3 pr-1">
                {(() => {
                  const suggested = getSuggestedIcons(categoryFormData.name);

                  const renderGrid = (icons: string[]) => (
                    <div className="grid grid-cols-7 gap-1.5">
                      {icons.map(icon => (
                        <button
                          key={icon}
                          type="button"
                          onClick={() => setCategoryFormData({ ...categoryFormData, icon })}
                          className={`aspect-square flex items-center justify-center text-xl rounded-lg border-2 transition-colors ${
                            categoryFormData.icon === icon
                              ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20'
                              : 'border-transparent hover:border-gray-300 dark:hover:border-gray-600'
                          }`}
                        >
                          {icon}
                        </button>
                      ))}
                    </div>
                  );

                  return (
                    <>
                      {suggested.length > 0 && (
                        <div>
                          <div className="text-xs font-medium text-primary-500 dark:text-primary-400 mb-1">{t('categories.suggested')}</div>
                          {renderGrid(suggested)}
                        </div>
                      )}
                      {ICON_GROUPS.map(group => (
                        <div key={group.tKey}>
                          <div className="text-xs font-medium text-gray-400 dark:text-gray-500 mb-1">{t(group.tKey)}</div>
                          {renderGrid(group.icons)}
                        </div>
                      ))}
                    </>
                  );
                })()}
              </div>
            </div>

            <div className="flex gap-3 pt-4">
              {isEditMode && selectedCategory ? (
                <>
                  <button
                    type="button"
                    onClick={() => setIsCategoryModalOpen(false)}
                    className="flex-1 btn-secondary"
                  >
                    {t('common.cancel')}
                  </button>
                  <button
                    type="submit"
                    disabled={!isCategoryFormValid}
                    className="flex-1 btn-primary disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {t('common.save')}
                  </button>
                </>
              ) : (
                <>
                  <button
                    type="button"
                    onClick={() => setIsCategoryModalOpen(false)}
                    className="flex-1 btn-secondary"
                  >
                    {t('common.cancel')}
                  </button>
                  <button
                    type="submit"
                    disabled={!isCategoryFormValid}
                    className="flex-1 btn-primary disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {t('common.create')}
                  </button>
                </>
              )}
            </div>
            {isEditMode && selectedCategory && (
              <button
                type="button"
                onClick={(e) => handleDeleteCategory(e, selectedCategory.id)}
                className="w-full px-4 py-2.5 rounded-lg bg-red-500 text-white hover:bg-red-600 transition-colors text-sm font-medium flex items-center justify-center gap-2"
              >
                <span className="text-base leading-none">🗑️</span>
                <span>{t('common.delete')}</span>
              </button>
            )}
          </form>
        </Modal>

        {/* Date Range Picker */}
        <DateRangePicker
          isOpen={isDatePickerOpen}
          onClose={() => setIsDatePickerOpen(false)}
          onConfirm={handleCustomPeriodConfirm}
          initialStart={startDate}
          initialEnd={endDate}
        />

        {/* Confirm Dialogs */}
        <ConfirmDialog
          isOpen={isDeleteCategoryDialogOpen}
          onClose={() => {
            setIsDeleteCategoryDialogOpen(false);
            setDeleteCategoryBlockedCount(0);
          }}
          onConfirm={deleteCategoryBlockedCount > 0 ? () => {} : confirmDeleteCategory}
          title={deleteCategoryBlockedCount > 0 ? t('categories.cannotDeleteTitle') : t('categories.deleteTitle')}
          message={
            deleteCategoryBlockedCount > 0
              ? t('categories.cannotDeleteMessage', { count: deleteCategoryBlockedCount })
              : t('categories.deleteMessage')
          }
          confirmText={deleteCategoryBlockedCount > 0 ? t('common.ok') : t('common.delete')}
          cancelText={deleteCategoryBlockedCount > 0 ? undefined : t('common.cancel')}
          isDestructive={deleteCategoryBlockedCount === 0}
        />

        <ConfirmDialog
          isOpen={isDeleteSubcategoryDialogOpen}
          onClose={() => {
            setIsDeleteSubcategoryDialogOpen(false);
            setDeleteSubcategoryBlockedCount(0);
          }}
          onConfirm={deleteSubcategoryBlockedCount > 0 ? () => {} : confirmDeleteSubcategory}
          title={deleteSubcategoryBlockedCount > 0 ? t('categories.cannotDeleteSubcategoryTitle') : t('categories.deleteSubcategoryTitle')}
          message={
            deleteSubcategoryBlockedCount > 0
              ? t('categories.cannotDeleteSubcategoryMessage', { count: deleteSubcategoryBlockedCount })
              : t('categories.deleteSubcategoryMessage')
          }
          confirmText={deleteSubcategoryBlockedCount > 0 ? t('common.ok') : t('common.delete')}
          cancelText={deleteSubcategoryBlockedCount > 0 ? undefined : t('common.cancel')}
          isDestructive={deleteSubcategoryBlockedCount === 0}
        />
      </div>
    </Layout>
  );
}

