              <thead className="bg-gray-50 dark:bg-gray-800/50">
                <tr className="text-gray-500 dark:text-gray-400 uppercase tracking-wide">
                  <th className="py-2 px-3 text-left whitespace-nowrap font-medium">Simbolo</th>
