import { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { apiService } from '../services/api';
import { supabase } from '../services/supabase';
import { useData } from '../contexts/DataContext';
import Layout from '../components/layout/Layout';
import Modal from '../components/common/Modal';
import { SkeletonPortfolioCard } from '../components/common/SkeletonLoader';
import InvestmentOrderForm, { type InvestmentOrderInput } from '../components/investments/InvestmentOrderForm';
import { useSkeletonCount } from '../hooks/useSkeletonCount';
import { useConfirm } from '../hooks/useConfirm';
import type { Portfolio, PortfolioFormData, Order, OrderFormData } from '../types';
import { useTranslation } from 'react-i18next';
import { useSettings } from '../contexts/SettingsContext';

const PF_BACKEND_URL = import.meta.env.VITE_PF_BACKEND_URL || 'https://portfolio-tracker-production-3bd4.up.railway.app';

type InitialPosition = InvestmentOrderInput;

interface PortfolioSummary {
  total_value: number;
  total_cost: number;
  total_gain_loss: number;
  total_gain_loss_pct: number;
  positions_count: number;
  xirr: number | null;
  reference_currency: string;
}


export default function PortfoliosPage() {
  const navigate = useNavigate();
  const { t } = useTranslation();
  const { formatCurrency } = useSettings();
  const { portfolios, isLoading, isInitialized, addPortfolio, updatePortfolio, deletePortfolio, updateTransaction: updateTransactionCache, deleteTransaction: deleteTransactionCache, refreshTransactions, activeProfile } = useData();
  const skeletonCount = useSkeletonCount('portfolios', portfolios.length, isLoading, 3);
  const { confirm: confirmDialog, dialog: confirmDialogEl } = useConfirm();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const portfolioDirtyRef = useRef(false);
  const guardedModalClose = async () => {
    if (portfolioDirtyRef.current) {
      const ok = await confirmDialog('Hai modifiche non salvate. Chiudere comunque?', { title: 'Modifiche non salvate', confirmText: 'Chiudi', cancelText: 'Annulla' });
      if (!ok) return;
      portfolioDirtyRef.current = false;
    }
    setIsModalOpen(false);
  };
  useEffect(() => { if (!isModalOpen) portfolioDirtyRef.current = false; }, [isModalOpen]);
  const [isEditMode, setIsEditMode] = useState(false);
  const [selectedPortfolio, setSelectedPortfolio] = useState<Portfolio | null>(null);
  const [portfolioOrders, setPortfolioOrders] = useState<Order[]>([]);
  const [isLoadingOrders, setIsLoadingOrders] = useState(false);
  const [summaries, setSummaries] = useState<Record<number, PortfolioSummary>>({});
  const [loadingSummaries, setLoadingSummaries] = useState(false);


  const [hideBalances, setHideBalances] = useState(() => localStorage.getItem('hideBalances') === 'true');
  const toggleHideBalances = () => {
    setHideBalances(h => { const next = !h; localStorage.setItem('hideBalances', String(next)); return next; });
  };
  const mask = (formatted: string) => '•'.repeat(formatted.length);

  const SUMMARIES_CACHE_KEY = 'pf_summaries_cache';
  const SUMMARIES_CACHE_TTL = 24 * 60 * 60 * 1000; // 24h
  const SUMMARIES_CACHE_TTL_EMPTY = 5 * 60 * 1000; // 5min se tutti i valori sono 0

  const loadSummariesFromServer = async (forceRefresh = false) => {
    if (!forceRefresh) {
      try {
        const raw = localStorage.getItem(SUMMARIES_CACHE_KEY);
        if (raw) {
          const { time, ttl, data } = JSON.parse(raw);
          const effectiveTtl = ttl ?? SUMMARIES_CACHE_TTL;
          if (Date.now() - time < effectiveTtl) {
            setSummaries(data);
            return;
          }
        }
      } catch (_) {}
    }
    setLoadingSummaries(true);
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session?.access_token) return;
      const token = session.access_token;
      const profileId = activeProfile?.id;
      const url = profileId
        ? `${PF_BACKEND_URL}/portfolios?profile_id=${profileId}`
        : `${PF_BACKEND_URL}/portfolios`;
      const res = await fetch(url, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const json = res.ok ? await res.json() : null;
      const map: Record<number, PortfolioSummary> = {};
      if (json?.portfolios) {
        for (const p of json.portfolios) {
          map[p.id] = {
            total_value: p.total_value ?? 0,
            total_cost: p.total_cost ?? 0,
            total_gain_loss: p.total_gain_loss ?? 0,
            total_gain_loss_pct: p.total_gain_loss_pct ?? 0,
            positions_count: p.positions_count ?? 0,
            xirr: p.xirr ?? null,
            reference_currency: p.reference_currency ?? 'EUR',
          };
        }
      }
      console.log('[portfolios] GET /portfolios response:', json);
      setSummaries(map);
      try {
        // Se almeno un portafoglio ha total_cost > 0 ma total_value === 0, il fetch prezzi è fallito
        // (es. Railway cold start o JustETF/yfinance lento). Non cachare il risultato per riprovare subito.
        const priceFetchFailed = Object.values(map).some(s => s.total_value === 0 && s.total_cost > 0);
        if (!priceFetchFailed) {
          const allTrulyEmpty = Object.values(map).length > 0 && Object.values(map).every(s => s.total_value === 0);
          const ttl = allTrulyEmpty ? SUMMARIES_CACHE_TTL_EMPTY : SUMMARIES_CACHE_TTL;
          localStorage.setItem(SUMMARIES_CACHE_KEY, JSON.stringify({ time: Date.now(), ttl, data: map }));
        }
      } catch (_) {}
    } catch (e) {
      console.error('Error fetching portfolio summaries:', e);
    } finally {
      setLoadingSummaries(false);
    }
  };

  useEffect(() => {
    if (!isInitialized || portfolios.length === 0) return;
    loadSummariesFromServer(false);
  }, [isInitialized, portfolios.length]);

  useEffect(() => {
    const onRefresh = () => loadSummariesFromServer(true);
    window.addEventListener('trackr:refresh', onRefresh);
    return () => window.removeEventListener('trackr:refresh', onRefresh);
  }, [portfolios]);

  const handleCreatePortfolio = () => {
    setSelectedPortfolio(null);
    setPortfolioOrders([]);
    setIsEditMode(false);
    setIsModalOpen(true);
  };

  const handleEditPortfolio = async (portfolio: Portfolio) => {
    setSelectedPortfolio(portfolio);
    setPortfolioOrders([]);
    setIsEditMode(true);
    setIsModalOpen(true);
    setIsLoadingOrders(true);
    try {
      const orders = await apiService.getOrders(portfolio.id);
      setPortfolioOrders(orders);
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoadingOrders(false);
    }
  };

  const handleSubmit = async (data: PortfolioFormData, initialPositions?: InitialPosition[]) => {
    if (isEditMode && selectedPortfolio) {
      const renamed = Boolean(data.name && data.name !== selectedPortfolio.name);
      const updated = await apiService.updatePortfolio(selectedPortfolio.id, data, selectedPortfolio.name);
      updatePortfolio(updated);
      if (renamed) {
        await refreshTransactions();
      }
    } else {
      const created = await apiService.createPortfolio({
        ...data,
        initial_capital: 0,
        history_mode: initialPositions && initialPositions.length > 0 ? 'positions_only' : 'full_orders',
      });
      if (initialPositions && initialPositions.length > 0) {
        const currency = data.reference_currency || 'EUR';
        await Promise.all(
          initialPositions.map(pos =>
            apiService.createOrder({
              portfolio_id: created.id,
              symbol: pos.symbol.trim().toUpperCase(),
              isin: pos.isin,
              name: pos.name,
              exchange: pos.exchange,
              ter: pos.ter,
              currency,
              quantity: pos.quantity,
              price: pos.price,
              commission: pos.commission,
              order_type: pos.orderType || 'buy',
              date: pos.date,
              instrument_type: pos.instrumentType,
            } as OrderFormData)
          )
        );
        localStorage.removeItem(SUMMARIES_CACHE_KEY);
      }
      addPortfolio(created);
      if (!initialPositions || initialPositions.length === 0) {
        setSummaries(prev => ({
          ...prev,
          [created.id]: {
            total_value: 0,
            total_cost: 0,
            total_gain_loss: 0,
            total_gain_loss_pct: 0,
            positions_count: 0,
            xirr: null,
            reference_currency: data.reference_currency || 'EUR',
          },
        }));
      }
    }
    setIsModalOpen(false);
  };

  const handleDelete = async (id: number) => {
    const ok = await confirmDialog(
      t(
        'portfolios.confirmDeletePortfolio',
        'Eliminare questo portafoglio? Verranno eliminati anche tutti gli ordini e le transazioni collegate. L\'azione non può essere annullata.'
      ),
      { title: t('portfolios.deletePortfolio'), confirmText: t('common.delete', 'Elimina'), isDestructive: true }
    );
    if (ok) {
      await apiService.deletePortfolio(id);
      deletePortfolio(id);
      setSummaries(prev => {
        const next = { ...prev };
        delete next[id];
        return next;
      });
      localStorage.removeItem(SUMMARIES_CACHE_KEY);
      await refreshTransactions();
      setIsModalOpen(false);
    }
  };

  const handleUpdateOrder = async (orderId: number, data: InvestmentOrderInput) => {
    const updated = await apiService.updateOrder(orderId, {
      symbol: data.symbol.trim().toUpperCase(),
      isin: data.isin,
      name: data.name,
      exchange: data.exchange,
      ter: data.ter,
      quantity: data.quantity,
      price: data.price,
      commission: data.commission,
      order_type: data.orderType || 'buy',
      date: data.date,
      instrument_type: data.instrumentType,
    });
    if (updated.transaction_id) {
      const grossAmount = updated.quantity * updated.price + updated.commission;
      const amount = updated.order_type === 'sell' ? -grossAmount : grossAmount;
      const updatedTransaction = await apiService.updateTransaction(updated.transaction_id, {
        amount,
        date: updated.date,
        ticker: updated.symbol,
        quantity: updated.quantity,
        price: updated.price,
      });
      updateTransactionCache(updatedTransaction);
    }
    setPortfolioOrders(prev => prev.map(order => order.id === orderId ? updated : order));
    localStorage.removeItem(SUMMARIES_CACHE_KEY);
    loadSummariesFromServer(true).catch(console.error);
  };

  const handleDeleteOrder = async (order: Order) => {
    const ok = await confirmDialog('Eliminare questo ordine?', {
      title: t('portfolios.editOrder'),
      confirmText: t('common.delete'),
      isDestructive: true,
    });
    if (!ok) return;

    await apiService.deleteOrder(order.id);
    if (order.transaction_id) {
      await apiService.deleteTransaction(order.transaction_id);
      deleteTransactionCache(order.transaction_id);
    }
    setPortfolioOrders(prev => prev.filter(existing => existing.id !== order.id));
    localStorage.removeItem(SUMMARIES_CACHE_KEY);
    loadSummariesFromServer(true).catch(console.error);
  };

  const showSkeleton = isLoading || !isInitialized;

  // Calcola totale investimenti sommando i summaries disponibili (per ora stesso reference_currency)
  const totalInvestments = Object.values(summaries).reduce((acc, s) => acc + s.total_value, 0);
  const totalPL = Object.values(summaries).reduce((acc, s) => acc + s.total_gain_loss, 0);
  const totalCost = Object.values(summaries).reduce((acc, s) => acc + s.total_cost, 0);
  const totalPLpct = totalCost > 0 ? (totalPL / totalCost) * 100 : 0;
  const hasSummaries = Object.keys(summaries).length > 0;

  return (
    <Layout>
      <div className="space-y-3">
        {showSkeleton
          ? Array.from({ length: skeletonCount }).map((_, i) => <SkeletonPortfolioCard key={i} />)
          : (
            <>
              {/* Banner Investimenti totali */}
              {portfolios.length > 0 && (
                <div className="sticky -top-3 z-20 -mx-4 px-4 -mt-3 pt-4 pb-3 bg-gray-50 dark:bg-gray-900 relative">
                  <div className="card py-5">
                    <div className="text-sm text-gray-500 dark:text-gray-400 mb-1 text-center">{t('portfolios.totalInvestments')}</div>
                    <div className="flex items-center justify-center">
                      <div className="flex-1" />
                      <div className="text-4xl font-bold">
                        {loadingSummaries && !hasSummaries
                          ? <span className="inline-block h-10 w-40 bg-gray-200 dark:bg-gray-700 rounded animate-pulse" />
                          : <span className={totalPL >= 0 ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'}>
                              {hideBalances ? mask(formatCurrency(totalInvestments)) : formatCurrency(totalInvestments)}
                            </span>
                        }
                      </div>
                      <div className="flex-1 flex justify-end pr-2">
                        <button
                          onClick={toggleHideBalances}
                          className="text-gray-400 dark:text-gray-500 text-xl outline-none focus:outline-none select-none"
                          style={{ WebkitTapHighlightColor: 'transparent' }}
                        >
                          {hideBalances ? '🙈' : '👁️'}
                        </button>
                      </div>
                    </div>
                    {hasSummaries && (
                      <div className={`text-sm text-center mt-1 ${totalPL >= 0 ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'}`}>
                        {hideBalances
                          ? mask((totalPL >= 0 ? '+' : '') + formatCurrency(totalPL))
                          : (totalPL >= 0 ? '+' : '') + formatCurrency(totalPL)
                        }
                        {!hideBalances && totalPLpct !== 0 && (
                          <span className="ml-1 opacity-75">({(totalPLpct >= 0 ? '+' : '') + totalPLpct.toFixed(1)}%)</span>
                        )}
                      </div>
                    )}
                  </div>
                  <div className="absolute left-0 right-0 h-6 bg-gradient-to-b from-gray-50 dark:from-gray-900 to-transparent pointer-events-none" style={{ top: '100%' }} />
                </div>
              )}

              {portfolios.length === 0 && (
                <div
                  className="card flex flex-col items-center justify-center py-14 cursor-pointer border-2 border-dashed border-primary-300 dark:border-primary-700 hover:border-primary-400 dark:hover:border-primary-600 transition-colors"
                  onClick={handleCreatePortfolio}
                  style={{ WebkitTapHighlightColor: 'transparent' }}
                >
                  <div className="w-16 h-16 rounded-full bg-primary-100 dark:bg-primary-900/30 flex items-center justify-center text-3xl mb-4">📈</div>
                  <div className="font-semibold text-gray-700 dark:text-gray-300 mb-1">{t('portfolios.noPortfolios')}</div>
                  <div className="text-sm text-gray-500 dark:text-gray-400 mb-4">{t('portfolios.noPortfoliosDesc')}</div>
                  <div className="flex items-center gap-2 bg-primary-500 hover:bg-primary-600 text-white px-5 py-2.5 rounded-xl font-medium text-sm transition-colors">
                    <span className="text-lg">+</span> {t('portfolios.newPortfolio')}
                  </div>
                </div>
              )}

              {portfolios.map((portfolio) => (
                <div
                  key={portfolio.id}
                  className="card cursor-pointer hover:shadow-lg transition-shadow"
                  onClick={() => navigate(`/portfolios/${portfolio.id}`)}
                >
                  <div className="flex items-start justify-between mb-1">
                    <div className="flex-1 min-w-0 flex items-center gap-2">
                      <span
                        className="text-2xl w-10 h-10 rounded-xl flex items-center justify-center flex-shrink-0"
                        style={{ backgroundColor: (portfolio.color ?? '#0ea5e9') + '22' }}
                      >{portfolio.icon ?? '📈'}</span>
                      <div className="font-medium text-gray-900 dark:text-gray-100">{portfolio.name}</div>
                    </div>
                    <div className="flex items-center gap-2 ml-2 shrink-0">
                      <div className="text-sm text-gray-400 dark:text-gray-500">{portfolio.reference_currency}</div>
                      <button
                        type="button"
                        onClick={(e) => { e.stopPropagation(); handleEditPortfolio(portfolio); }}
                        className="text-gray-400 dark:text-gray-500 hover:text-primary-600 dark:hover:text-primary-400 p-1 rounded border border-gray-200 dark:border-gray-700 hover:border-primary-300 dark:hover:border-primary-700 transition-colors"
                        style={{ WebkitTapHighlightColor: 'transparent' }}
                        title={t('common.edit', 'Modifica')}
                      >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-3.5 w-3.5" viewBox="0 0 20 20" fill="currentColor">
                          <path fillRule="evenodd" d="M11.49 3.17c-.38-1.56-2.6-1.56-2.98 0a1.532 1.532 0 01-2.286.948c-1.372-.836-2.942.734-2.106 2.106.54.886.061 2.042-.947 2.287-1.561.379-1.561 2.6 0 2.978a1.532 1.532 0 01.947 2.287c-.836 1.372.734 2.942 2.106 2.106a1.532 1.532 0 012.287.947c.379 1.561 2.6 1.561 2.978 0a1.533 1.533 0 012.287-.947c1.372.836 2.942-.734 2.106-2.106a1.533 1.533 0 01.947-2.287c1.561-.379 1.561-2.6 0-2.978a1.532 1.532 0 01-.947-2.287c.836-1.372-.734-2.942-2.106-2.106a1.532 1.532 0 01-2.287-.947zM10 13a3 3 0 100-6 3 3 0 000 6z" clipRule="evenodd" />
                        </svg>
                      </button>
                    </div>
                  </div>

                  {(() => {
                    const sm = summaries[portfolio.id];
                    if (loadingSummaries && !sm) return (
                      <div className="pt-3 mt-2 border-t border-gray-200 dark:border-gray-700">
                        <div className="h-6 w-32 bg-gray-200 dark:bg-gray-700 rounded animate-pulse" />
                      </div>
                    );
                    if (!sm || sm.positions_count === 0) return (
                      <div className="pt-3 mt-2 border-t border-gray-200 dark:border-gray-700">
                        <div className="min-h-[72px] rounded-2xl bg-gray-50 dark:bg-gray-800/50 px-4 py-3 flex items-center">
                          <div className="text-xs uppercase tracking-[0.14em] text-gray-400 dark:text-gray-500">
                            {t('portfolios.noPositionsInPortfolio')}
                          </div>
                        </div>
                      </div>
                    );
                    return (
                      <div className="pt-3 mt-2 border-t border-gray-200 dark:border-gray-700">
                        <div className="min-h-[72px] rounded-2xl bg-gray-50 dark:bg-gray-800/50 px-4 py-3 grid grid-cols-2 gap-4 items-center">
                          <div className="min-w-0 self-center">
                            <div className="text-xs uppercase tracking-[0.14em] text-gray-400 dark:text-gray-500 mb-1 leading-none">
                              {t('portfolios.currentValueLabel')}
                            </div>
                            <div className="text-xl font-semibold text-gray-900 dark:text-gray-100 leading-tight">
                              {hideBalances ? mask(formatCurrency(sm.total_value, sm.reference_currency)) : formatCurrency(sm.total_value, sm.reference_currency)}
                            </div>
                          </div>
                          <div className="min-w-0 text-right self-center">
                            <div className="text-xs uppercase tracking-[0.14em] text-gray-400 dark:text-gray-500 mb-1 leading-none">
                              {t('portfolios.plLabel')}
                            </div>
                            <div className={`text-xl font-semibold leading-tight ${sm.total_gain_loss >= 0 ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'}`}>
                              {hideBalances
                                ? mask(formatCurrency(sm.total_gain_loss, sm.reference_currency))
                                : formatCurrency(sm.total_gain_loss, sm.reference_currency)
                              }
                            </div>
                            <div className={`text-xs font-medium mt-0.5 ${sm.total_gain_loss >= 0 ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'}`}>
                              {hideBalances ? '•••' : (sm.total_gain_loss_pct >= 0 ? '+' : '') + sm.total_gain_loss_pct.toFixed(1) + '%'}
                            </div>
                          </div>
                        </div>
                      </div>
                    );
                  })()}
                </div>
              ))}

              {/* Add button — only when there are portfolios */}
              {portfolios.length > 0 && (
                <div
                  className="card flex items-center justify-center py-10 border-2 border-dashed border-gray-200 dark:border-gray-700 cursor-pointer outline-none select-none"
                  style={{ WebkitTapHighlightColor: 'transparent' }}
                  onClick={handleCreatePortfolio}
                >
                  <div className="w-10 h-10 rounded-full border-2 border-gray-300 dark:border-gray-600 flex items-center justify-center text-gray-400 dark:text-gray-500 font-bold text-2xl leading-none">+</div>
                </div>
              )}

              {/* Analyze link */}
              {portfolios.length > 0 && (
                <a
                  href="https://portfolio-tracker-one-tau.vercel.app/"
                  target="_blank"
                  rel="noopener noreferrer"
                  className="flex items-center justify-center gap-2 py-3 text-sm text-primary-600 dark:text-primary-400 font-medium"
                >
                  <span>📊</span>
                  <span>{t('portfolios.analyzePortfolio')}</span>
                  <svg className="w-3.5 h-3.5 opacity-70" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                  </svg>
                </a>
              )}
            </>
          )
        }

        <Modal
          isOpen={isModalOpen}
          onClose={guardedModalClose}
          title={isEditMode ? (selectedPortfolio?.name || t('portfolios.newPortfolio')) : t('portfolios.newPortfolio')}
        >
          <PortfolioForm
            onSubmit={handleSubmit}
            onDelete={isEditMode && selectedPortfolio ? () => handleDelete(selectedPortfolio.id) : undefined}
            onCancel={guardedModalClose}
            onDirtyChange={dirty => { portfolioDirtyRef.current = dirty; }}
            existingPortfolios={portfolios}
            editingPortfolioId={selectedPortfolio?.id}
            initialData={selectedPortfolio ? {
              name: selectedPortfolio.name,
              icon: selectedPortfolio.icon,
              color: selectedPortfolio.color,
              initial_capital: selectedPortfolio.initial_capital,
              reference_currency: selectedPortfolio.reference_currency,
            } : undefined}
            isEditMode={isEditMode}
            orders={portfolioOrders}
            isLoadingOrders={isLoadingOrders}
            onOrderUpdate={handleUpdateOrder}
            onOrderDelete={handleDeleteOrder}
          />
        </Modal>
        {confirmDialogEl}
      </div>
    </Layout>
  );
}

interface PortfolioFormProps {
  onSubmit: (data: PortfolioFormData, initialPositions?: InitialPosition[]) => Promise<void>;
  onDelete?: () => Promise<void>;
  onCancel: () => void;
  onDirtyChange?: (dirty: boolean) => void;
  existingPortfolios: Portfolio[];
  editingPortfolioId?: number;
  initialData?: PortfolioFormData;
  isEditMode?: boolean;
  orders: Order[];
  isLoadingOrders: boolean;
  onOrderUpdate: (orderId: number, data: InvestmentOrderInput) => Promise<void>;
  onOrderDelete: (order: Order) => Promise<void>;
}

function PortfolioForm({ onSubmit, onDelete, onCancel, onDirtyChange, existingPortfolios, editingPortfolioId, initialData, isEditMode, orders, isLoadingOrders, onOrderUpdate, onOrderDelete }: PortfolioFormProps) {
  const { t } = useTranslation();
  const { formatCurrency } = useSettings();
  const { confirm: confirmDialog, dialog: confirmDialogEl } = useConfirm();
  const PORTFOLIO_ICONS = ['📈','📉','💼','🏦','💰','💵','💶','💷','🪙','💳','🏧','📊','🏛️','🌍','🌎','🌏','⭐','🔑','🎯','🚀','💡','🛡️','⚡','🌱'];
  const PORTFOLIO_COLORS = ['#0ea5e9','#6366f1','#8b5cf6','#ec4899','#ef4444','#f97316','#eab308','#22c55e','#14b8a6','#64748b','#1d4ed8','#7c3aed'];
  const [name, setName] = useState(initialData?.name || '');
  const [icon, setIcon] = useState(initialData?.icon || '📈');
  const [color, setColor] = useState(initialData?.color || '#0ea5e9');
  const [currency, setCurrency] = useState(initialData?.reference_currency || 'EUR');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [initialPositions, setInitialPositions] = useState<InitialPosition[]>([]);
  const [isPositionModalOpen, setIsPositionModalOpen] = useState(false);
  const [editingInitialPositionIndex, setEditingInitialPositionIndex] = useState<number | null>(null);
  const [editingOrder, setEditingOrder] = useState<Order | null>(null);
  const normalizedPortfolioName = name.trim().toLocaleLowerCase();
  const isDuplicatePortfolioName = normalizedPortfolioName !== '' && existingPortfolios.some(
    (portfolio) => portfolio.id !== editingPortfolioId && portfolio.name.trim().toLocaleLowerCase() === normalizedPortfolioName
  );
  const isPortfolioFormValid = name.trim() !== '' && !isDuplicatePortfolioName;
  const markDirty = () => { onDirtyChange?.(true); };
  const renderOrderCard = (params: {
    key: string | number;
    symbol: string;
    quantity: number;
    price: number;
    commission?: number;
    currency: string;
    date?: string;
    orderType?: 'buy' | 'sell';
    onClick: () => void;
  }) => {
    const total = params.quantity * params.price + (params.commission || 0);
    return (
      <button
        key={params.key}
        type="button"
        onClick={params.onClick}
        className="w-full flex items-center justify-between py-2.5 px-3 rounded-lg bg-gray-50 dark:bg-gray-800/50 text-sm text-left transition-colors hover:bg-gray-100 dark:hover:bg-gray-800 active:bg-gray-100 dark:active:bg-gray-800"
      >
        <div className="flex items-center gap-3 min-w-0">
          {params.orderType && (
            <span className={`inline-flex items-center self-center text-xs font-medium px-1.5 py-0.5 rounded shrink-0 ${
              params.orderType === 'buy'
                ? 'bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400'
                : 'bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-400'
            }`}>
              {params.orderType === 'buy' ? 'BUY' : 'SELL'}
            </span>
          )}
          <div className="min-w-0">
            <div className="font-mono font-medium text-gray-900 dark:text-gray-100 truncate">{params.symbol}</div>
            <div className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">
              {`${params.quantity}x ${formatCurrency(params.price, params.currency)}`}
            </div>
          </div>
        </div>
        <div className="shrink-0 ml-3 text-right self-center">
          <div className="text-gray-700 dark:text-gray-300 font-medium">{formatCurrency(total, params.currency)}</div>
          {params.date && (
            <div className="text-xs text-gray-400 dark:text-gray-500 mt-0.5">{params.date}</div>
          )}
        </div>
      </button>
    );
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;
    if (isDuplicatePortfolioName) return;
    setIsLoading(true);
    setError('');
    try {
      await onSubmit({
        name,
        icon,
        color,
        reference_currency: currency,
      }, initialPositions.length > 0 ? initialPositions : undefined);
    } catch (err: any) {
      setError('Errore durante il salvataggio');
      setIsLoading(false);
    }
  };

  return (<>
    <form onSubmit={handleSubmit} noValidate autoComplete="off" className="space-y-3">
      <div>
        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">{t('portfolios.name')}</label>
        <input
          type="text"
          value={name}
          onChange={(e) => { setName(e.target.value); markDirty(); }}
          className={`input-field ${isDuplicatePortfolioName ? '!border-red-500 dark:!border-red-500' : ''}`}
          placeholder="Es: Fineco, TradeRepublic..."
          autoComplete="off" autoCorrect="off" spellCheck={false}
        />
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">{t('accounts.icon')}</label>
        <div className="flex gap-1.5 overflow-x-auto pb-1" style={{ scrollbarWidth: 'none' }}>
          {PORTFOLIO_ICONS.map(ic => (
            <button
              key={ic}
              type="button"
              onClick={() => { setIcon(ic); markDirty(); }}
              className={`flex-shrink-0 w-9 h-9 flex items-center justify-center text-xl rounded-lg border-2 transition-colors ${
                icon === ic
                  ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20'
                  : 'border-transparent hover:border-gray-300 dark:hover:border-gray-600'
              }`}
            >
              {ic}
            </button>
          ))}
        </div>
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">Colore</label>
        <div className="flex gap-2 overflow-x-auto p-2" style={{ scrollbarWidth: 'none' }}>
          {PORTFOLIO_COLORS.map(c => (
            <button
              key={c}
              type="button"
              onClick={() => { setColor(c); markDirty(); }}
              className={`flex-shrink-0 w-7 h-7 rounded-full transition-transform ${color === c ? 'scale-125 ring-2 ring-offset-1 ring-gray-400 dark:ring-gray-500' : 'hover:scale-110'}`}
              style={{ backgroundColor: c }}
            />
          ))}
        </div>
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">{t('portfolios.currency')}</label>
        <div className="flex gap-2">
          {[{ code: 'EUR', symbol: '€' }, { code: 'USD', symbol: '$' }, { code: 'GBP', symbol: '£' }, { code: 'CHF', symbol: 'Fr' }].map(c => (
            <button
              key={c.code}
              type="button"
              onClick={() => { setCurrency(c.code); markDirty(); }}
              className={`flex-1 py-2 rounded-lg text-sm font-medium border-2 transition-colors ${
                currency === c.code
                  ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20 text-primary-700 dark:text-primary-300'
                  : 'border-gray-200 dark:border-gray-700 text-gray-600 dark:text-gray-400'
              }`}
            >
              {c.symbol} {c.code}
            </button>
          ))}
        </div>
      </div>


      {/* Posizioni iniziali (solo create mode) */}
      {!isEditMode && (
        <div className="border-t border-gray-200 dark:border-gray-700 pt-4">
          <div className="flex items-center justify-between mb-2">
            <div className="text-sm font-medium text-gray-700 dark:text-gray-300">
              {t('portfolios.initialPositions')} {initialPositions.length > 0 && `(${initialPositions.length})`}
            </div>
            <button
              type="button"
              onClick={() => setIsPositionModalOpen(true)}
              className="text-sm text-primary-600 dark:text-primary-400 font-medium"
            >
              {t('portfolios.addPosition')}
            </button>
          </div>
          {initialPositions.length === 0 ? (
            <div className="text-sm text-gray-400 dark:text-gray-500 text-center py-3">
              {t('portfolios.noPositions')}
            </div>
          ) : (
            <div className="space-y-1 max-h-40 overflow-y-auto">
              {initialPositions.map((pos, i) => renderOrderCard({
                key: i,
                symbol: pos.symbol,
                quantity: pos.quantity,
                price: pos.price,
                commission: pos.commission,
                currency,
                date: pos.date,
                orderType: pos.orderType || 'buy',
                onClick: () => setEditingInitialPositionIndex(i),
              }))}
            </div>
          )}
        </div>
      )}

      {/* Ordini (solo edit mode) */}
      {isEditMode && (
        <div className="border-t border-gray-200 dark:border-gray-700 pt-4">
          <div className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
            {t('portfolios.orders')} ({isLoadingOrders ? '...' : orders.length})
          </div>
          {isLoadingOrders ? (
            <div className="text-sm text-gray-400 dark:text-gray-500 text-center py-3">{t('common.loading')}</div>
          ) : orders.length === 0 ? (
            <div className="text-sm text-gray-400 dark:text-gray-500 text-center py-3">{t('portfolios.noOrders')}</div>
          ) : (
            <div className="space-y-1 max-h-48 overflow-y-auto">
              {orders.map(order => renderOrderCard({
                key: order.id,
                symbol: order.symbol,
                quantity: order.quantity,
                price: order.price,
                commission: order.commission,
                currency: order.currency,
                date: order.date,
                orderType: order.order_type as 'buy' | 'sell',
                onClick: () => setEditingOrder(order),
              }))}
            </div>
          )}
        </div>
      )}

      {error && (
        <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 text-red-600 dark:text-red-400 px-4 py-3 rounded-lg text-sm">
          {error}
        </div>
      )}

      <div className="flex gap-3 pt-2">
        <button type="button" onClick={onCancel} className="flex-1 btn-secondary" disabled={isLoading}>
          {t('common.cancel')}
        </button>
        <button type="submit" className="flex-1 btn-primary disabled:opacity-50 disabled:cursor-not-allowed" disabled={isLoading || !isPortfolioFormValid}>
          {isLoading ? '...' : isEditMode ? t('common.save') : t('common.create')}
        </button>
      </div>

      {isEditMode && onDelete && (
        <button
          type="button"
          onClick={onDelete}
          className="w-full px-4 py-2.5 rounded-lg bg-red-500 text-white hover:bg-red-600 transition-colors text-sm font-medium"
          disabled={isLoading}
        >
          {t('portfolios.deletePortfolio')}
        </button>
      )}
    </form>

    <Modal isOpen={isPositionModalOpen} onClose={() => setIsPositionModalOpen(false)} title={t('portfolios.newPosition')}>
      <InvestmentOrderForm
        currency={currency}
        existingOrders={initialPositions.map((pos, index) => ({
          id: index,
          symbol: pos.symbol,
          isin: pos.isin,
          name: pos.name,
          exchange: pos.exchange,
          currency,
          quantity: pos.quantity,
          price: pos.price,
          commission: pos.commission,
          order_type: pos.orderType || 'buy',
          instrument_type: pos.instrumentType,
        }))}
        onSubmit={(pos) => {
          setInitialPositions(prev => [...prev, pos]);
          markDirty();
          setIsPositionModalOpen(false);
        }}
        onCancel={() => setIsPositionModalOpen(false)}
      />
    </Modal>
    <Modal isOpen={editingInitialPositionIndex !== null} onClose={() => setEditingInitialPositionIndex(null)} title={t('portfolios.editOrder')}>
      {editingInitialPositionIndex !== null && initialPositions[editingInitialPositionIndex] && (
        <>
          <InvestmentOrderForm
            currency={currency}
            existingOrders={initialPositions.map((pos, index) => ({
              id: index,
              symbol: pos.symbol,
              isin: pos.isin,
              name: pos.name,
              exchange: pos.exchange,
              currency,
              quantity: pos.quantity,
              price: pos.price,
              commission: pos.commission,
              order_type: pos.orderType || 'buy',
              instrument_type: pos.instrumentType,
            }))}
            ignoreOrderId={editingInitialPositionIndex}
            initialData={initialPositions[editingInitialPositionIndex]}
            submitLabel={t('common.save')}
            onSubmit={async (data) => {
              setInitialPositions(prev => prev.map((pos, index) => index === editingInitialPositionIndex ? data : pos));
              markDirty();
              setEditingInitialPositionIndex(null);
            }}
            onCancel={() => setEditingInitialPositionIndex(null)}
          />
          <button
            type="button"
            onClick={async () => {
              if (editingInitialPositionIndex === null) return;
              if (await confirmDialog('Rimuovere questa posizione?', { title: 'Rimuovi posizione', confirmText: 'Rimuovi', isDestructive: true })) {
                setInitialPositions(prev => prev.filter((_, index) => index !== editingInitialPositionIndex));
                markDirty();
                setEditingInitialPositionIndex(null);
              }
            }}
            className="mt-3 w-full px-4 py-2.5 rounded-lg bg-red-500 text-white hover:bg-red-600 transition-colors text-sm font-medium"
          >
            {t('common.delete')}
          </button>
        </>
      )}
    </Modal>
    <Modal isOpen={!!editingOrder} onClose={() => setEditingOrder(null)} title={t('portfolios.editOrder')}>
      {editingOrder && (
        <>
          <InvestmentOrderForm
            currency={editingOrder.currency}
            existingOrders={orders}
            ignoreOrderId={editingOrder.id}
            initialData={{
              symbol: editingOrder.symbol,
              isin: editingOrder.isin,
              name: editingOrder.name,
              exchange: editingOrder.exchange,
              ter: editingOrder.ter,
              quantity: editingOrder.quantity,
              price: editingOrder.price,
              commission: editingOrder.commission,
              date: editingOrder.date,
              orderType: editingOrder.order_type as 'buy' | 'sell',
              instrumentType: editingOrder.instrument_type as 'etf' | 'stock' | 'bond' | undefined,
            }}
            submitLabel={t('common.save')}
            onSubmit={async (data) => {
              await onOrderUpdate(editingOrder.id, data);
              setEditingOrder(null);
            }}
            onCancel={() => setEditingOrder(null)}
          />
          <button
            type="button"
            onClick={async () => {
              await onOrderDelete(editingOrder);
              setEditingOrder(null);
            }}
            className="mt-3 w-full px-4 py-2.5 rounded-lg bg-red-500 text-white hover:bg-red-600 transition-colors text-sm font-medium"
          >
            {t('common.delete')}
          </button>
        </>
      )}
    </Modal>
    {confirmDialogEl}
  </>);
}

import { useState, useEffect, useRef } from 'react';
import type { ProfileMember } from '../types';
import { useNavigate } from 'react-router-dom';
import { apiService } from '../services/api';
import { supabase } from '../services/supabase';
import { useAuth } from '../contexts/AuthContext';
import { useData } from '../contexts/DataContext';
import Modal from '../components/common/Modal';
import KakeboImport from '../components/KakeboImport';
import { useConfirm } from '../hooks/useConfirm';
import { useTranslation } from 'react-i18next';
import i18n from '../i18n';
import { useSettings } from '../contexts/SettingsContext';

function getTheme(): 'dark' | 'light' | 'system' {
  const saved = localStorage.getItem('theme');
  if (saved === 'dark' || saved === 'light') return saved;
  return 'system';
}

function applyTheme(theme: 'dark' | 'light' | 'system') {
  const root = document.documentElement;
  if (theme === 'dark') {
    root.classList.add('dark');
    localStorage.setItem('theme', 'dark');
  } else if (theme === 'light') {
    root.classList.remove('dark');
    localStorage.setItem('theme', 'light');
  } else {
    localStorage.removeItem('theme');
    if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }
}

export default function SettingsPage() {
  const navigate = useNavigate();
  const { logout, user } = useAuth();
  const { t } = useTranslation();
  const { numberFormat, setNumberFormat } = useSettings();
  const { confirm: confirmDialog, dialog: confirmDialogEl } = useConfirm();
  const { userProfiles, activeProfile, switchProfile, createUserProfile, updateUserProfile, deleteUserProfile, leaveProfile } = useData();
  const [theme, setTheme] = useState<'dark' | 'light' | 'system'>(getTheme);
  const [currentLang, setCurrentLang] = useState<string>(() => {
    const l = i18n.language?.slice(0, 2);
    return ['it', 'es'].includes(l) ? l : 'en';
  });

  // Password
  const [showChangePassword, setShowChangePassword] = useState(false);
  const [currentPassword, setCurrentPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [passwordMsg, setPasswordMsg] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const [passwordLoading, setPasswordLoading] = useState(false);

  // Profili
  const [editingProfileId, setEditingProfileId] = useState<string | null>(null);
  const [editingProfileName, setEditingProfileName] = useState('');
  const [newProfileName, setNewProfileName] = useState('');
  const [showAddProfile, setShowAddProfile] = useState(false);
  const [profileLoading, setProfileLoading] = useState(false);
  const [profileMsg, setProfileMsg] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

  // Condivisione profili
  const [expandedProfileId, setExpandedProfileId] = useState<string | null>(null);
  const [profileMembers, setProfileMembers] = useState<Record<string, ProfileMember[]>>({});
  const [inviteEmail, setInviteEmail] = useState('');
  const [inviteRole, setInviteRole] = useState<'editor' | 'viewer'>('editor');
  const [inviteLoading, setInviteLoading] = useState(false);
  const [inviteMsg, setInviteMsg] = useState<string | null>(null);

  const [exportMessage, setExportMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null);
  const [showKakeboImport, setShowKakeboImport] = useState(false);
  const kakeboDirtyRef = useRef(false);
  const guardedKakeboClose = async () => {
    if (kakeboDirtyRef.current) {
      const ok = await confirmDialog('Hai modifiche non salvate. Chiudere comunque?', { title: 'Modifiche non salvate', confirmText: 'Chiudi', cancelText: 'Annulla', noBottomOffset: true });
      if (!ok) return;
      kakeboDirtyRef.current = false;
    }
    setShowKakeboImport(false);
  };

  useEffect(() => { applyTheme(theme); }, [theme]);

  const handleThemeChange = (t: 'dark' | 'light' | 'system') => {
    setTheme(t);
    applyTheme(t);
  };

  const handleLanguageChange = (lang: string) => {
    i18n.changeLanguage(lang);
    localStorage.setItem('lang', lang);
    setCurrentLang(lang);
  };

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (newPassword !== confirmPassword) {
      setPasswordMsg({ type: 'error', text: t('settings.errorPasswordMismatch') });
      return;
    }
    if (newPassword.length < 6) {
      setPasswordMsg({ type: 'error', text: t('settings.errorPasswordTooShort') });
      return;
    }
    setPasswordLoading(true);
    setPasswordMsg(null);
    try {
      // Verifica la password attuale
      const email = user?.name ?? '';
      const { error: signInError } = await supabase.auth.signInWithPassword({ email, password: currentPassword });
      if (signInError) {
        setPasswordMsg({ type: 'error', text: t('settings.errorCurrentPassword') });
        setPasswordLoading(false);
        return;
      }
      const { error } = await supabase.auth.updateUser({ password: newPassword });
      if (error) throw error;
      setPasswordMsg({ type: 'success', text: t('settings.successPasswordChanged') });
      setCurrentPassword('');
      setNewPassword('');
      setConfirmPassword('');
      setShowChangePassword(false);
    } catch (err: any) {
      setPasswordMsg({ type: 'error', text: err.message || t('settings.errorPasswordChange') });
    } finally {
      setPasswordLoading(false);
    }
  };

  const handleSaveProfileName = async (id: string) => {
    const name = editingProfileName.trim();
    if (!name) return;
    setProfileLoading(true);
    try {
      await updateUserProfile(id, name);
      setEditingProfileId(null);
    } catch {
      setProfileMsg({ type: 'error', text: t('settings.errorProfileSave') });
    } finally {
      setProfileLoading(false);
    }
  };

  const handleAddProfile = async () => {
    const name = newProfileName.trim();
    if (!name) return;
    setProfileLoading(true);
    try {
      await createUserProfile(name);
      setNewProfileName('');
      setShowAddProfile(false);
    } catch {
      setProfileMsg({ type: 'error', text: t('settings.errorProfileSave') });
    } finally {
      setProfileLoading(false);
    }
  };

  const handleDeleteProfile = async (id: string) => {
    if (userProfiles.length <= 1) return;
    const profileName = userProfiles.find(p => p.id === id)?.name || '';
    const confirmed = await confirmDialog(
      `Eliminare il profilo "${profileName}"? Verranno cancellati definitivamente tutti i conti, le transazioni, le categorie e i portafogli associati.`,
      { title: 'Elimina profilo', confirmText: 'Elimina', isDestructive: true, noBottomOffset: true }
    );
    if (!confirmed) return;
    setProfileLoading(true);
    try {
      if (activeProfile?.id === id) {
        const other = userProfiles.find(p => p.id !== id)!;
        await switchProfile(other);
      }
      await deleteUserProfile(id);
    } catch {
      setProfileMsg({ type: 'error', text: t('settings.errorProfileDelete') });
    } finally {
      setProfileLoading(false);
    }
  };

  const handleToggleMembers = async (profileId: string) => {
    if (expandedProfileId === profileId) {
      setExpandedProfileId(null);
      return;
    }
    setExpandedProfileId(profileId);
    setInviteEmail('');
    setInviteMsg(null);
    if (!profileMembers[profileId]) {
      const members = await apiService.getProfileMembers(profileId);
      setProfileMembers(prev => ({ ...prev, [profileId]: members }));
    }
  };

  const handleInvite = async (profileId: string) => {
    if (!inviteEmail.trim()) return;
    setInviteLoading(true);
    setInviteMsg(null);
    try {
      await apiService.inviteToProfile(profileId, inviteEmail.trim(), inviteRole);
      setInviteMsg(t('settings.inviteSent'));
      setInviteEmail('');
    } catch (e: any) {
      if (e.message === 'already_member') setInviteMsg(t('settings.inviteErrorAlreadyMember'));
      else if (e.message === 'invite_pending') setInviteMsg(t('settings.inviteErrorPending'));
      else if (e.message === 'rate_limited') setInviteMsg(t('settings.inviteErrorRateLimit'));
      else setInviteMsg(t('settings.inviteError'));
    } finally {
      setInviteLoading(false);
    }
  };

  const handleRemoveMember = async (profileId: string, userId: string) => {
    const confirmed = await confirmDialog(t('settings.confirmRemoveMember'), { isDestructive: true, noBottomOffset: true });
    if (!confirmed) return;
    await apiService.removeProfileMember(profileId, userId);
    setProfileMembers(prev => ({
      ...prev,
      [profileId]: (prev[profileId] ?? []).filter(m => m.user_id !== userId),
    }));
  };

  const handleLeaveProfile = async (profileId: string) => {
    const confirmed = await confirmDialog(t('settings.confirmLeaveProfile'), { isDestructive: true, noBottomOffset: true });
    if (!confirmed) return;
    setProfileLoading(true);
    try {
      await leaveProfile(profileId);
      setExpandedProfileId(null);
    } catch {
      setProfileMsg({ type: 'error', text: t('settings.errorProfileDelete') });
    } finally {
      setProfileLoading(false);
    }
  };

  const handleExport = async () => {
    try {
      await apiService.exportData();
      setExportMessage({ type: 'success', text: t('settings.successExported') });
    } catch {
      setExportMessage({ type: 'error', text: t('settings.errorExporting') });
    }
  };

  const themeOptions: { value: 'light' | 'dark' | 'system'; labelKey: string; icon: string }[] = [
    { value: 'light', labelKey: 'settings.themeLight', icon: '☀️' },
    { value: 'system', labelKey: 'settings.themeSystem', icon: '⚙️' },
    { value: 'dark', labelKey: 'settings.themeDark', icon: '🌙' },
  ];

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 pb-10">
      {/* Header con back button — mobile only */}
      <div className="md:hidden sticky top-0 z-10 bg-gray-50 dark:bg-gray-900 border-b border-gray-200 dark:border-gray-800 px-4 py-3 flex items-center gap-3">
        <button
          onClick={() => navigate(-1)}
          className="w-9 h-9 flex items-center justify-center rounded-full text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors"
        >
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7" />
          </svg>
        </button>
        <h1 className="text-lg font-semibold text-gray-900 dark:text-white">{t('settings.title')}</h1>
      </div>

      <div className="hidden md:flex items-center gap-3 px-4 pt-8 pb-2 max-w-2xl mx-auto">
        <button
          onClick={() => navigate(-1)}
          className="w-9 h-9 flex items-center justify-center rounded-full text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors"
        >
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M15 19l-7-7 7-7" />
          </svg>
        </button>
        <h1 className="text-xl font-bold text-gray-900 dark:text-white">{t('settings.title')}</h1>
      </div>

      <div className="max-w-lg md:max-w-2xl mx-auto px-4 pt-6 md:pt-2 space-y-5">

        {/* Profili */}
        <section className="card">
          <h2 className="text-sm font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-4">{t('settings.profiles')}</h2>

          {profileMsg && (
            <div className={`mb-3 text-sm px-3 py-2 rounded-lg ${profileMsg.type === 'success' ? 'bg-green-50 dark:bg-green-900/20 text-green-700 dark:text-green-400' : 'bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400'}`}>
              {profileMsg.text}
            </div>
          )}

          <div className="space-y-2">
            {userProfiles.map(profile => (
              <div key={profile.id} className={`rounded-xl border-2 transition-colors ${activeProfile?.id === profile.id ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20' : 'border-gray-200 dark:border-gray-700'}`}>
                {/* Riga principale profilo */}
                <div className="flex items-center gap-2 px-3 py-2.5 min-h-[56px]">
                  {editingProfileId === profile.id ? (
                    <input
                      className="flex-1 input-field text-sm"
                      value={editingProfileName}
                      onChange={e => setEditingProfileName(e.target.value)}
                      onKeyDown={e => { if (e.key === 'Enter') handleSaveProfileName(profile.id); if (e.key === 'Escape') setEditingProfileId(null); }}
                      autoFocus
                    />
                  ) : (
                    <button
                      className="flex-1 text-left flex items-center gap-2"
                      onClick={() => { if (activeProfile?.id !== profile.id) switchProfile(profile); }}
                    >
                      <span className="font-medium text-sm text-gray-800 dark:text-gray-100">{profile.name}</span>
                      {activeProfile?.id === profile.id && (
                        <span className="text-xs text-primary-500 font-normal">{t('settings.activeProfile')}</span>
                      )}
                      {profile.role !== 'owner' && (
                        <span className="text-xs text-gray-400 dark:text-gray-500 font-normal">
                          {profile.role === 'editor' ? '✏️' : '👁️'} {t(`settings.role_${profile.role}`)}
                        </span>
                      )}
                    </button>
                  )}

                  {editingProfileId === profile.id ? (
                    <div className="flex gap-1">
                      <button onClick={() => setEditingProfileId(null)} className="text-xs px-2 py-1 rounded bg-gray-200 dark:bg-gray-600 text-gray-700 dark:text-gray-200">{t('common.cancel')}</button>
                      <button onClick={() => handleSaveProfileName(profile.id)} disabled={profileLoading} className="text-xs px-2 py-1 rounded bg-primary-500 text-white">{t('common.save')}</button>
                    </div>
                  ) : (
                    <div className="flex items-center gap-1">
                      {profile.role === 'owner' && (
                        <>
                          <button
                            onClick={() => { setEditingProfileId(profile.id); setEditingProfileName(profile.name); }}
                            className="p-1.5 rounded-lg text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-700"
                          >
                            <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                              <path strokeLinecap="round" strokeLinejoin="round" d="M15.232 5.232l3.536 3.536M9 11l6-6 3 3-6 6H9v-3z" />
                            </svg>
                          </button>
                          <button
                            onClick={() => handleToggleMembers(profile.id)}
                            className="p-1.5 rounded-lg text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center gap-0.5"
                            title={t('settings.manageMembers')}
                          >
                            <span>👥</span>
                            {(profile.member_count ?? 1) > 1 && (
                              <span className="text-[10px] font-semibold leading-none">{profile.member_count}</span>
                            )}
                          </button>
                          {userProfiles.length > 1 && (
                            <button
                              onClick={() => handleDeleteProfile(profile.id)}
                              disabled={profileLoading}
                              className="p-1.5 rounded-lg text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20"
                            >
                              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                              </svg>
                            </button>
                          )}
                        </>
                      )}
                      {profile.role !== 'owner' && (
                        <button
                          onClick={() => handleLeaveProfile(profile.id)}
                          className="text-xs px-2 py-1 rounded text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20"
                        >{t('settings.leaveProfile')}</button>
                      )}
                    </div>
                  )}
                </div>

                {/* Sezione membri espandibile (solo owner) */}
                {profile.role === 'owner' && expandedProfileId === profile.id && (
                  <div className="border-t border-gray-100 dark:border-gray-700 px-3 pb-3 pt-2">
                    <p className="text-xs font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide mb-2">
                      {t('settings.members')}
                    </p>

                    {/* Lista membri correnti */}
                    {(profileMembers[profile.id] ?? []).map(member => (
                      <div key={member.user_id} className="flex items-center gap-2 mb-1.5">
                        <div className="w-7 h-7 rounded-full bg-primary-100 dark:bg-primary-900/40 flex items-center justify-center text-xs font-semibold text-primary-600 dark:text-primary-400">
                          {(member.email ?? '?')[0].toUpperCase()}
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className="text-sm truncate">{member.email ?? member.user_id}</p>
                          <p className="text-xs text-gray-400">{t(`settings.role_${member.role}`)}</p>
                        </div>
                        {member.role !== 'owner' && (
                          <button
                            onClick={() => handleRemoveMember(profile.id, member.user_id)}
                            className="text-xs text-red-400 hover:text-red-600 px-1"
                          >{t('settings.remove')}</button>
                        )}
                      </div>
                    ))}

                    {/* Feedback invito */}
                    {inviteMsg && (
                      <p className="text-xs text-primary-600 dark:text-primary-400 mb-2">{inviteMsg}</p>
                    )}

                    {/* Form invito */}
                    <div className="flex gap-1.5 mt-2">
                      <input
                        className="flex-1 input-field text-sm"
                        placeholder={t('settings.inviteEmailPlaceholder')}
                        value={inviteEmail}
                        onChange={e => { setInviteEmail(e.target.value); setInviteMsg(null); }}
                        onKeyDown={e => { if (e.key === 'Enter') handleInvite(profile.id); }}
                        type="email"
                      />
                      <select
                        className="input-field text-sm w-auto px-2"
                        value={inviteRole}
                        onChange={e => setInviteRole(e.target.value as 'editor' | 'viewer')}
                      >
                        <option value="editor">{t('settings.role_editor')}</option>
                        <option value="viewer">{t('settings.role_viewer')}</option>
                      </select>
                      <button
                        onClick={() => handleInvite(profile.id)}
                        disabled={inviteLoading || !inviteEmail.trim()}
                        className="btn-primary text-sm px-3"
                      >{t('settings.invite')}</button>
                    </div>
                  </div>
                )}
              </div>
            ))}

            {/* Aggiungi profilo */}
            {showAddProfile ? (
              <div className="flex flex-col gap-2 mt-1">
                <input
                  className="w-full px-3 py-2 text-sm rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-primary-500 focus:border-transparent"
                  placeholder={t('settings.profileNamePlaceholder')}
                  value={newProfileName}
                  onChange={e => setNewProfileName(e.target.value)}
                  onKeyDown={e => { if (e.key === 'Enter') handleAddProfile(); if (e.key === 'Escape') setShowAddProfile(false); }}
                  autoFocus
                />
                <div className="flex gap-2">
                <button onClick={() => setShowAddProfile(false)} className="btn-secondary text-sm flex-1">{t('common.cancel')}</button>
                <button onClick={handleAddProfile} disabled={profileLoading || !newProfileName.trim()} className="btn-primary text-sm flex-1">{t('common.add')}</button>
