async function getCurrentUserId(): Promise<string> {
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error('Non autenticato');
  return user.id;
}

// ==================== MAPPERS ====================

function mapAccount(row: any): Account {
  return {
    id: row.id,
    user_id: row.user_id,
    name: row.name,
    icon: row.icon,
    initial_balance: row.initial_balance ?? 0,
    current_balance: row.current_balance,
    is_favorite: row.is_favorite ?? false,
    created_at: row.created_at,
    updated_at: row.updated_at,
    currencies: (row.account_currencies ?? []).map((c: any) => ({
      id: c.id, account_id: c.account_id, currency: c.currency, initial_balance: Number(c.initial_balance),
    })),
  };
}

function mapSubcategory(row: any): Subcategory {
  return {
    id: row.id,
    category_id: row.category_id,
    name: row.name,
    created_at: row.created_at,
    updated_at: row.updated_at,
  };
}

function mapCategory(row: any): CategoryWithStats {
  return {
    id: row.id,
    user_id: row.user_id,
    name: row.name,
    icon: row.icon,
    color: row.color || null,
    category_type: row.category_type,
    created_at: row.created_at,
    updated_at: row.updated_at,
    subcategories: (row.subcategories || []).map(mapSubcategory),
    total_amount: 0,
    transaction_count: 0,
  };
}

function mapTransaction(row: any): Transaction {
  return {
    id: row.id,
    userId: row.user_id,
    account_id: row.account_id,
    type: row.type,
    category: row.category,
    subcategory: row.subcategory,
    amount: row.amount,
    description: row.description,
    date: row.date,
    created_at: row.created_at,
    updated_at: row.updated_at,
    ticker: row.ticker,
    quantity: row.quantity,
    price: row.price,
    recurring_id: row.recurring_id ?? undefined,
    currency: row.currency ?? 'EUR',
    base_amount: row.base_amount != null ? Number(row.base_amount) : null,
  };
}

function mapTransfer(row: any): Transfer {
  return {
    id: row.id,
    user_id: row.user_id,
    from_account_id: row.from_account_id,
    to_account_id: row.to_account_id,
    amount: row.amount,
    description: row.description,
    date: row.date,
    created_at: row.created_at,
    updated_at: row.updated_at,
    from_currency: row.from_currency ?? 'EUR',
    to_currency: row.to_currency ?? 'EUR',
    to_amount: row.to_amount != null ? Number(row.to_amount) : null,
  };
}

function mapRecurringTransaction(row: any): RecurringTransaction {
  return {
    id: row.id,
    user_id: row.user_id,
    account_id: row.account_id,
    type: row.type,
    portfolio_id: row.portfolio_id,
    category: row.category,
    subcategory: row.subcategory,
    amount: row.amount,
    description: row.description,
    frequency: row.frequency,
    start_date: row.start_date,
    next_due_date: row.next_due_date,
    ticker: row.ticker,
    isin: row.isin,
    instrument_name: row.instrument_name,
    exchange: row.exchange,
    instrument_type: row.instrument_type,
    order_type: row.order_type,
    currency: row.currency ?? 'EUR',
    quantity: row.quantity,
    price: row.price,
    created_at: row.created_at,
  };
}

// Calcola la prossima data in base alla frequenza
function mapPortfolio(row: any): Portfolio {
  return {
    id: row.id,
    user_id: row.user_id,
    name: row.name,
    icon: row.icon ?? '📈',
    color: row.color ?? '#0ea5e9',
    history_mode: row.history_mode ?? 'full_orders',
    initial_capital: row.initial_capital ?? 0,
    reference_currency: row.reference_currency ?? 'EUR',
    risk_free_source: row.risk_free_source ?? '',
    market_benchmark: row.market_benchmark ?? '',
    created_at: row.created_at,
    total_value: row.total_value,
    total_cost: row.total_cost,
    total_gain_loss: row.total_gain_loss,
