// ==================== API SERVICE ====================

class ApiService {

  // ==================== ACTIVE PROFILE ====================

  private _activeProfileId: string | null = null;

  setActiveProfile(profileId: string) {
    this._activeProfileId = profileId;
    localStorage.setItem('activeProfileId', profileId);
  }

  getActiveProfileId(): string {
    if (!this._activeProfileId) {
      this._activeProfileId = localStorage.getItem('activeProfileId');
    }
    if (!this._activeProfileId) throw new Error('Nessun profilo attivo');
    return this._activeProfileId;
  }

  clearActiveProfile() {
    this._activeProfileId = null;
    localStorage.removeItem('activeProfileId');
  }

  private normalizeName(value: string): string {
    return value.trim().toLocaleLowerCase();
  }

  private async assertUniqueProfileName(
    table: 'accounts' | 'categories' | 'portfolios',
    name: string,
    excludeId?: number
  ): Promise<void> {
    const profileId = this.getActiveProfileId();
    const normalized = this.normalizeName(name);
    const { data, error } = await supabase.from(table).select('id, name').eq('profile_id', profileId);
    if (error) throw error;
    const duplicate = (data || []).some((row: any) => row.id !== excludeId && this.normalizeName(row.name || '') === normalized);
    if (duplicate) throw new Error('duplicate-name');
  }

  private async assertUniqueSubcategoryName(categoryId: number, name: string, excludeId?: number): Promise<void> {
    const normalized = this.normalizeName(name);
    const { data, error } = await supabase.from('subcategories').select('id, name').eq('category_id', categoryId);
    if (error) throw error;
    const duplicate = (data || []).some((row: any) => row.id !== excludeId && this.normalizeName(row.name || '') === normalized);
    if (duplicate) throw new Error('duplicate-name');
  }

  // ==================== PROFILES ====================

  async getProfiles(): Promise<UserProfile[]> {
    const { data, error } = await supabase.rpc('get_my_profiles');
    if (error) throw error;
    return (data ?? []).map((row: any) => ({
      id: row.id,
      user_id: row.uid,
      name: row.name,
      role: row.role as ProfileRole,
      member_count: Number(row.member_count ?? 1),
      created_at: row.created_at,
    }));
  }

  async createProfile(name: string): Promise<UserProfile> {
    const userId = await getCurrentUserId();
    const { data, error } = await supabase
      .from('profiles')
      .insert({ user_id: userId, name })
      .select()
      .single();
    if (error) throw error;
    return { id: data.id, user_id: data.user_id, name: data.name, role: 'owner' as ProfileRole, created_at: data.created_at };
  }

  async updateProfile(id: string, name: string): Promise<void> {
    const { error } = await supabase.from('profiles').update({ name }).eq('id', id);
    if (error) throw error;
  }

  async deleteProfile(id: string): Promise<void> {
    const { error } = await supabase.from('profiles').delete().eq('id', id);
    if (error) throw error;
  }

  async getProfileMembers(profileId: string): Promise<ProfileMember[]> {
    const { data, error } = await supabase
      .from('profile_members')
      .select('*')
      .eq('profile_id', profileId)
      .order('joined_at');
    if (error) throw error;
    return data ?? [];
  }

  async inviteToProfile(profileId: string, email: string, role: 'editor' | 'viewer'): Promise<void> {
    const { error } = await supabase.rpc('create_profile_invitation', {
      p_profile_id: profileId,
      p_email: email,
      p_role: role,
    });
    if (error) {
      if (error.message.includes('already_member')) throw new Error('already_member');
      if (error.message.includes('invite_pending')) throw new Error('invite_pending');
      if (error.message.includes('rate_limited')) throw new Error('rate_limited');
      if (error.message.includes('not_owner')) throw new Error('not_owner');
      throw error;
    }
  }

  async removeProfileMember(profileId: string, userId: string): Promise<void> {
    const { error } = await supabase
      .from('profile_members')
      .delete()
      .eq('profile_id', profileId)
      .eq('user_id', userId);
    if (error) throw error;
  }

  async cancelInvitation(invitationId: string): Promise<void> {
    const { error } = await supabase
      .from('profile_share_invitations')
      .update({ status: 'cancelled' })
      .eq('id', invitationId)
      .eq('status', 'pending');
    if (error) throw error;
  }

  async leaveProfile(profileId: string): Promise<void> {
    const userId = await getCurrentUserId();
    const { error } = await supabase
      .from('profile_members')
      .delete()
      .eq('profile_id', profileId)
      .eq('user_id', userId)
      .neq('role', 'owner');
    if (error) throw error;
  }

  async getPendingInvitations(): Promise<ProfileInvitation[]> {
    const { data, error } = await supabase
      .from('profile_share_invitations')
      .select('*, profiles(name)')
      .eq('status', 'pending')
      .gt('expires_at', new Date().toISOString())
      .order('created_at', { ascending: false });
    if (error) throw error;
    return (data ?? []).map((row: any) => ({
      id: row.id,
      profile_id: row.profile_id,
      profile_name: row.profiles?.name ?? '',
      invited_by_email: row.invited_by,
      role: row.role,
      status: row.status,
      expires_at: row.expires_at,
    }));
  }

  async acceptInvitation(invitationId: string): Promise<void> {
    const { error } = await supabase.rpc('accept_profile_invitation', {
      p_invitation_id: invitationId,
    });
    if (error) {
      if (error.message.includes('invalid_invitation')) throw new Error('invalid_invitation');
      if (error.message.includes('not_recipient')) throw new Error('not_recipient');
      throw error;
    }
  }

  async rejectInvitation(invitationId: string): Promise<void> {
    const { error } = await supabase
      .from('profile_share_invitations')
      .update({ status: 'rejected' })
      .eq('id', invitationId);
    if (error) throw error;
  }

  // AUTH

  getCurrentUser(): User | null {
    const userStr = localStorage.getItem('user');
    if (!userStr) return null;
    try { return JSON.parse(userStr); } catch { return null; }
  }

  async profileExists(): Promise<boolean> {
    const userId = await getCurrentUserId();
    const { data } = await supabase.from('profiles').select('id').eq('id', userId).single();
    return !!data;
  }

  // ==================== ACCOUNTS ====================

  async getAccounts(): Promise<Account[]> {
    const profileId = this.getActiveProfileId();
    const { data, error } = await supabase.from('accounts').select('*, account_currencies(*)').eq('profile_id', profileId).order('id');
    if (error) throw error;
    return (data || []).map(mapAccount);
  }

  async createDefaultAccounts(lang: Lang = 'en'): Promise<Account[]> {
    const userId = await getCurrentUserId();
    const profileId = this.getActiveProfileId();
    const defaults = DEFAULT_ACCOUNTS[lang].map(a => ({ ...a, user_id: userId, profile_id: profileId }));
    const { data, error } = await supabase.from('accounts').insert(defaults).select();
    if (error) throw error;
    const accounts = data || [];
    const currencyRows = accounts.map((account: any) => ({
      account_id: account.id,
      profile_id: profileId,
      currency: 'EUR',
      initial_balance: account.initial_balance ?? 0,
    }));
    if (currencyRows.length > 0) {
      const { error: currencyError } = await supabase.from('account_currencies').insert(currencyRows);
      if (currencyError) throw currencyError;
    }
    return accounts.map(mapAccount);
  }

  async createAccount(formData: AccountFormData): Promise<Account> {
    const userId = await getCurrentUserId();
    const profileId = this.getActiveProfileId();
    await this.assertUniqueProfileName('accounts', formData.name);
    const { current_balance: _, ...dbData } = formData as any;
    const { data, error } = await supabase
      .from('accounts')
      .insert({ ...dbData, user_id: userId, profile_id: profileId })
      .select()
      .single();
    if (error) throw error;
    const { error: ccError } = await supabase.from('account_currencies').insert({
      account_id: data.id,
      profile_id: this.getActiveProfileId(),
      currency: 'EUR',
      initial_balance: formData.initial_balance ?? 0,
    });
    if (ccError) throw ccError;
    return mapAccount(data);
  }

  async updateAccount(id: number, formData: Partial<AccountFormData>): Promise<Account> {
    if (typeof formData.name === 'string') {
      await this.assertUniqueProfileName('accounts', formData.name, id);
    }
    const { current_balance: _, ...dbData } = formData as any;
    const { data, error } = await supabase
      .from('accounts')
      .update(dbData)
      .eq('id', id)
      .select()
      .single();
    if (error) throw error;
    return mapAccount(data);
  }

  async deleteAccount(id: number): Promise<void> {
    const { error } = await supabase.from('accounts').delete().eq('id', id);
    if (error) throw error;
  }

  // ==================== ACCOUNT CURRENCIES ====================

  async addAccountCurrency(accountId: number, currency: CurrencyCode, initialBalance: number): Promise<AccountCurrency> {
    const { data, error } = await supabase.from('account_currencies')
      .insert({ account_id: accountId, profile_id: this.getActiveProfileId(), currency, initial_balance: initialBalance })
      .select().single();
    if (error) throw error;
    return { id: data.id, account_id: data.account_id, currency: data.currency, initial_balance: Number(data.initial_balance) };
  }

  async updateAccountCurrency(id: number, initialBalance: number): Promise<AccountCurrency> {
    const { data, error } = await supabase.from('account_currencies')
      .update({ initial_balance: initialBalance }).eq('id', id).select().single();
    if (error) throw error;
    return { id: data.id, account_id: data.account_id, currency: data.currency, initial_balance: Number(data.initial_balance) };
  }

  async removeAccountCurrency(id: number): Promise<void> {
    const { data: row, error: e0 } = await supabase.from('account_currencies').select('*').eq('id', id).single();
    if (e0) throw e0;
    if (row.currency === 'EUR') throw new Error('cannot_remove_eur');
    const [tx, trFrom, trTo] = await Promise.all([
      supabase.from('transactions').select('id', { count: 'exact', head: true }).eq('account_id', row.account_id).eq('currency', row.currency),
      supabase.from('transfers').select('id', { count: 'exact', head: true }).eq('from_account_id', row.account_id).eq('from_currency', row.currency),
      supabase.from('transfers').select('id', { count: 'exact', head: true }).eq('to_account_id', row.account_id).eq('to_currency', row.currency),
    ]);
    if ((tx.count ?? 0) + (trFrom.count ?? 0) + (trTo.count ?? 0) > 0) throw new Error('currency_in_use');
    const { error } = await supabase.from('account_currencies').delete().eq('id', id);
    if (error) throw error;
  }

  // ==================== CATEGORIES ====================

  async getCategories(): Promise<CategoryWithStats[]> {
    const profileId = this.getActiveProfileId();
    const { data, error } = await supabase.from('categories').select('*, subcategories(*)').eq('profile_id', profileId).order('id');
    if (error) throw error;
    return (data || []).map(mapCategory);
  }

  async createDefaultCategories(existing: CategoryWithStats[], lang: Lang = 'en'): Promise<CategoryWithStats[]> {
    const userId = await getCurrentUserId();
    const profileId = this.getActiveProfileId();
    const hasExpense = existing.some(c => c.category_type === 'expense' || c.category_type == null);
    const hasIncome = existing.some(c => c.category_type === 'income');

    const toCreate = DEFAULT_CATEGORIES[lang].filter(cat => {
      const isExpense = cat.category_type === 'expense' || cat.category_type === null;
      const isIncome = cat.category_type === 'income';
      return (isExpense && !hasExpense) || (isIncome && !hasIncome);
    }).map(cat => ({ ...cat, user_id: userId, profile_id: profileId }));

    if (toCreate.length === 0) return existing;

    const { data, error } = await supabase.from('categories').insert(toCreate).select('*, subcategories(*)');
    if (error) throw error;
    return [...existing, ...(data || []).map(mapCategory)];
  }

  async createCategory(formData: CategoryFormData): Promise<Category> {
    const userId = await getCurrentUserId();
    const profileId = this.getActiveProfileId();
    await this.assertUniqueProfileName('categories', formData.name);
    const { data, error } = await supabase
      .from('categories')
      .insert({ ...formData, user_id: userId, profile_id: profileId })
      .select('*, subcategories(*)')
      .single();
    if (error) throw error;
    return mapCategory(data);
  }

  async updateCategory(id: number, formData: Partial<CategoryFormData>): Promise<Category> {
    if (typeof formData.name === 'string') {
      await this.assertUniqueProfileName('categories', formData.name, id);
    }
    const { data, error } = await supabase
      .from('categories')
      .update(formData)
      .eq('id', id)
      .select('*, subcategories(*)')
      .single();
    if (error) throw error;
    return mapCategory(data);
  }

  async deleteCategory(id: number): Promise<void> {
    const { error } = await supabase.from('categories').delete().eq('id', id);
    if (error) throw error;
  }

  // ==================== SUBCATEGORIES ====================

  async createSubcategory(categoryId: number, formData: SubcategoryFormData): Promise<Subcategory> {
    await this.assertUniqueSubcategoryName(categoryId, formData.name);
    const { data, error } = await supabase
      .from('subcategories')
      .insert({ ...formData, category_id: categoryId })
      .select()
      .single();
    if (error) throw error;
    return mapSubcategory(data);
  }

  async updateSubcategory(subcategoryId: number, name: string): Promise<Subcategory> {
    const { data: current, error: currentError } = await supabase
      .from('subcategories')
      .select('category_id')
      .eq('id', subcategoryId)
      .single();
    if (currentError) throw currentError;
    await this.assertUniqueSubcategoryName(current.category_id, name, subcategoryId);
    const { data, error } = await supabase
      .from('subcategories')
      .update({ name })
      .eq('id', subcategoryId)
      .select()
      .single();
    if (error) throw error;
    return mapSubcategory(data);
  }

  async deleteSubcategory(_categoryId: number, subcategoryId: number): Promise<void> {
    const { error } = await supabase.from('subcategories').delete().eq('id', subcategoryId);
    if (error) throw error;
  }

  // ==================== TRANSACTIONS ====================

  async getTransactions(params?: {
    startDate?: string;
    endDate?: string;
    category?: string;
    type?: string;
  }): Promise<Transaction[]> {
    let query = supabase
      .from('transactions')
      .select('*')
      .order('date', { ascending: false })
      .order('id', { ascending: false });

    query = query.eq('profile_id', this.getActiveProfileId());
    if (params?.startDate) query = query.gte('date', params.startDate);
    if (params?.endDate) query = query.lte('date', params.endDate);
    if (params?.category) query = query.eq('category', params.category);
    if (params?.type) query = query.eq('type', params.type);

    const { data, error } = await query;
    if (error) throw error;
    return (data || []).map(mapTransaction);
  }

  async createTransaction(formData: TransactionFormData): Promise<Transaction> {
    const userId = await getCurrentUserId();
    const profileId = this.getActiveProfileId();
    const { recurrence: _, portfolio_id: _pid, isin: _isin, instrument_name: _iname, exchange: _exch, instrument_type: _itype, order_type: _otype, ter: _ter, ...dbData } = formData;
    const currency = (formData.currency ?? 'EUR') as CurrencyCode;
    const base_amount = await computeBaseAmount(formData.amount, currency, formData.date);
    const { data, error } = await supabase
      .from('transactions')
      .insert({ ...dbData, user_id: userId, profile_id: profileId, currency, base_amount })
      .select()
      .single();
    if (error) throw error;
    return mapTransaction(data);
  }

